-- textfix/character_speech.lua — SINH TỰ ĐỘNG bởi tools/tao_textfix.py từ vietnamese.po.
-- ĐỪNG SỬA TAY: sửa vietnamese.po rồi chạy lại tool. Xem docstring của tool.

(function()
    textfix["\n\"Day 195 - Energy\"\n\n\"Eureka. Lunar forms radiate boundless energy. Containable. Obedient, even? Control may be possible. Endless applications... if stability holds.\"\n"] = "\n\"Ngày 195 - Năng lượng\"\n\n\"Eureka. Các dạng mặt trăng tỏa ra năng lượng vô biên. Có thể chứa được. Vâng lời, thậm chí? Có thể kiểm soát được. Ứng dụng vô tận... nếu sự ổn định được giữ vững.\"\n"
    textfix["\n\"Day 226 - Containment Measures\"\n\n\"Area of containment necessary prior to experimentation. Consider implementing a kinetic and teleportational dampening field?\"\n"] = "\n\"Ngày 226 - Các biện pháp ngăn chặn\"\n\n\"Khu vực ngăn chặn cần thiết trước khi thử nghiệm. Hãy cân nhắc triển khai trường giảm chấn động học và dịch chuyển tức thời?\"\n"
    textfix["\n\"Day 354 - Heat Signature Detection\"\n\n\"Preliminary thermal tracking functional. However, response irregularities suggest vulnerability to rudimentary interference - false positives observed with minimal thermal masking.\"\n"] = "\n\"Ngày 354 - Phát hiện dấu hiệu nhiệt\"\n\n\"Chức năng theo dõi nhiệt sơ bộ. Tuy nhiên, những phản ứng bất thường cho thấy dễ bị ảnh hưởng bởi sự can thiệp thô sơ - dương tính giả được quan sát thấy khi đeo mặt nạ nhiệt tối thiểu.\"\n"
    textfix["\n\"Day 418 - Electrifying!\"\n\n\"Interesting. Can redirect controlled electric discharge for practical (and offensive) applications. Truly remarkable potential. Note to self: don appropriate insulative layers next time. That last zap was... unexpectedly exhilarating.\"\n"] = "\n\"Ngày 418 - Điện khí hóa!\"\n\n\"Thú vị. Có thể chuyển hướng phóng điện có kiểm soát cho các ứng dụng thực tế (và gây khó chịu). Tiềm năng thực sự đáng chú ý. Lưu ý cho bản thân: hãy đeo các lớp cách điện thích hợp vào lần tới. Cú va chạm cuối cùng đó... phấn khích đến không ngờ.\"\n"
    textfix["\n\"Day 56 - Lunar Mutations Study\"\n\n\"It seems as though these strange entities that emerged from the rifts are in search of living hosts... or perhaps once living.\"\n\n\"NOTE: The following creatures warrant immediate study as I suspect they may be the most viable as hosts:\"\n\n• Frog\n• Pengull\n• Varg\n• Koalefant\n• Deerclops\n\n\"Other possible Rift entity host candidates:\"\n\n• Grass Gekko\n• Hound\n• Bearger\n• Mosling\n"] = "\n\"Ngày 56 - Nghiên cứu về Đột biến Mặt trăng\"\n\n\"Có vẻ như những thực thể kỳ lạ này xuất hiện từ các khe nứt đang tìm kiếm vật chủ sống... hoặc có lẽ đã từng sống.\"\n\n\"LƯU Ý: Những sinh vật sau đây cần được nghiên cứu ngay lập tức vì tôi nghi ngờ chúng có thể là vật chủ khả thi nhất:\"\n\n→ Ếch\n Cánh cụt biển\n Varg\n^ Koalefant\n Deerclops\n\n\"Có thể khác Các ứng cử viên chủ trì thực thể rạn nứt:\"\n\n→ Grass Gekko\n→ Hound\n→ Bearger\n Mosling\n"
    textfix["\n\"Day 89 - Material Study\"\n\n\"Thulecite appears sufficient to contain lunar entities. Structural integrity holds under moderate strain. Further testing advised.\"\n"] = "\n\"Ngày 89 - Nghiên cứu Vật liệu\"\n\n\"Thulecite dường như đủ để chứa các thực thể mặt trăng. Tính toàn vẹn cấu trúc được duy trì dưới sức căng vừa phải. Nên thử nghiệm thêm.\"\n"
    textfix["\n*Grows a magnificent beard"] = "\n*Sở hữu bộ râu tuyệt đẹp"
    textfix["\nCan fix easy, florp!"] = "\nCó thể sửa chữa dễ dàng, florp!"
    textfix["\nCan fix it!"] = "\nCó thể sửa được!"
    textfix["\nDon't worry, I know how to fix it!"] = "\nĐừng lo, tôi biết cách khắc phục!"
    textfix["\nI CAN FIX THIS"] = "\nTÔI CÓ THỂ KHẮC PHỤC ĐIỀU NÀY"
    textfix["\nI believe I could repair that."] = "\nTôi tin rằng tôi có thể sửa chữa được điều đó."
    textfix["\nI can repair this."] = "\nTôi có thể sửa cái này."
    textfix["\nI could restore it."] = "\nTôi có thể khôi phục nó."
    textfix["\nI do believe I can repair this."] = "\nTôi tin rằng tôi có thể sửa chữa được điều này."
    textfix["\nI think I can fix this!"] = "\nTôi nghĩ tôi có thể khắc phục được điều này!"
    textfix["\nI'd rather not eat the same old thing again."] = "\nTôi thà không ăn lại món cũ."
    textfix["\nI've repaired complicated timepieces, fixing this should be easy!"] = "\nTôi đã sửa chữa những chiếc đồng hồ phức tạp, việc sửa lỗi này thật dễ dàng!"
    textfix["\nIt'd be a pleasure to fix it."] = "\nRất vui được sửa nó."
    textfix["\nMighty brain could make this better!"] = "\nBộ não mạnh mẽ có thể làm điều này tốt hơn!"
    textfix["\nMy shadow puppets should be able to draw from its power..."] = "\nNhững con rối bóng của tôi có thể sử dụng sức mạnh của nó..."
    textfix["\nSelect a random survivor"] = "\nChọn một người sống sót ngẫu nhiên"
    textfix["\nUnlike my heart, this could be mended."] = "\nKhông giống như trái tim tôi, điều này có thể được hàn gắn."
    textfix["\nWe can repair it."] = "\nChúng ta có thể sửa nó."
    textfix[" - No Bind - "] = " - Chưa có nút - "
    textfix[" -- Select new input -- "] = " -- Chọn nút nhập đầu vào -- "
    textfix[" / MIN"] = " / Phút"
    textfix[" / SEC"] = " / Giây"
    textfix[" Are those scales wooden? Interesting."] = "Những chiếc cân đó có phải bằng gỗ không? Hấp dẫn."
    textfix[" Day"] = " Ngày"
    textfix[" Days"] = " Ngày"
    textfix[" HA HA"] = "HÀ HÀ"
    textfix[" Happy now? What do I get?"] = "Bây giờ hạnh phúc chứ? Tôi được gì?"
    textfix[" I'll show you my GOOD lures."] = " Tôi sẽ cho bạn thấy những mồi nhử tốt của tôi."
    textfix[" INSULATION"] = " VẬT LIỆU CÁCH NHIỆT"
    textfix[" ITEMS"] = " MẶT HÀNG"
    textfix[" PLANAR DAMAGE"] = " Thiệt hại phẳng"
    textfix[" PLANAR DEFENSE"] = " Phòng thủ phẳng"
    textfix[" RANGE"] = " PHẠM VI"
    textfix[" SPLASH DAMAGE"] = " Thiệt hại giật gân"
    textfix[" USES"] = " Sử dụng"
    textfix[" from split screen"] = " từ màn hình chia nhỏ"
    textfix[" in the caves"] = " trong các hang động"
    textfix[" to Disconnect"] = " để ngừng kết nối"
    textfix["\" from your ban list?\nThis will affect all servers you create."] = "\" khỏi danh sách cấm của bạn?\nĐiều này sẽ ảnh hưởng đến tất cả máy chủ bạn tạo."
    textfix["\"'Neath full moon's light, ye place the key;\nA rod whose call the stars doth heed.\nBut be ye warned, 'fore prize be claimed,\nSurvive the horde, lest ye be maimed.\""] = "\"'Trước ánh trăng tròn, bạn đặt chìa khóa;\nMột cây gậy có tiếng gọi mà các vì sao sẽ chú ý.\nNhưng hãy cảnh báo, trước khi nhận được giải thưởng,\nHãy sống sót sau đám đông, kẻo bị thương.\""
    textfix["\"A Pinetree Pioneer is always prepared!\""] = "\"Một chiếc mũ ca nô luôn sẵn sàng!\""
    textfix["\"A Pinetree Pioneer is patient and polite.\" But uh, hurry up please?"] = "\"Pinetree Pioneer kiên nhẫn và lịch sự.\" Nhưng ừ, nhanh lên nhé?"
    textfix["\"A Task Complete\""] = "\"Nhiệm vụ đã hoàn thành\""
    textfix["\"A flare was sent up from the forest last night. I know I should have set out immediately to help, but... well... I suppose I hesitated too long by the comforting glow of my campfire, and before I knew it the flare had faded from view. I do hope whoever it was is alright...\" -W"] = "\"Một ngọn lửa đã được gửi lên từ khu rừng đêm qua. Tôi biết lẽ ra tôi nên lập tức đến giúp đỡ, nhưng... à... tôi cho rằng tôi đã do dự quá lâu trước ánh sáng dễ chịu của ngọn lửa trại, và trước khi tôi kịp nhận ra thì ngọn lửa đã mờ dần khỏi tầm nhìn. Tôi hy vọng dù đó là ai thì vẫn ổn...\" -W"
    textfix["\"A mighty Winter's Feast makes Wolfgang even mightier!\""] = "\"Lễ hội mùa đông hoành tráng khiến Wolfgang thậm chí còn hùng mạnh hơn!\""
    textfix["\"A princely guise, with moonlit ties!\""] = "\"Vóc dáng hoàng tử, với cà vạt dưới ánh trăng!\""
    textfix["\"A rose to symbolize the flames of passion.\""] = "\"Một bông hồng để tượng trưng cho ngọn lửa của đam mê.\""
    textfix["\"A sickly, sweet rose, plucked in its prime. Why?\""] = "\"Một bông hồng ngọt ngào, ốm yếu, bị hái khi còn non. Tại sao vậy?\""
    textfix["\"ALL FLESHLINGS WILL BE CRUSHED\""] = "\"Tất cả các loại thịt sẽ bị nghiền nát\""
    textfix["\"ART\" IS JUST RECREATING STUFF YOU SEE LYING AROUND"] = "\" NGHỆ THUẬT \" CHỈ LÀ TÁI TẠO NHỮNG ĐỒ BẠN THẤY NẰM XUNG QUANH"
    textfix["\"Abigail and I never fight.\""] = "\"Abigail và tôi không bao giờ chiến đấu.\""
    textfix["\"Abigail and I shared everything.\""] = "\"Abigail và tôi đã chia sẻ mọi thứ.\""
    textfix["\"Abigail? Come back! I'm not done playing with you.\""] = "\"Abigail? quay lại đi. Chúng mình chưa chơi với nhau xong mà.\""
    textfix["\"After some experimentation, I've discovered the perfect ratio of holly and jolly.\""] = "\"Sau một số thử nghiệm, tôi đã phát hiện ra tỷ lệ hoàn hảo giữa nhựa ruồi và nhựa vui.\""
    textfix["\"Age makes fools of us all.\""] = "\"Tuổi làm cho tất cả chúng ta.\""
    textfix["\"Ah, the reckless abandon of youth. To think I used to dabble in fiction...\""] = "\"À, sự bỏ rơi tuổi trẻ một cách liều lĩnh. Nghĩ đến việc tôi từng say mê tiểu thuyết...\""
    textfix["\"Ah, to see the world through rose-colored glasses.\""] = "\"Ah, để nhìn thế giới qua kính màu hồng.\""
    textfix["\"Ahhh. Home\""] = "\"Ahhh. Nhà\""
    textfix["\"All can be lost except my taste!\""] = "\"Tất cả có thể bị mất ngoại trừ sở thích của tôi!\""
    textfix["\"All fire, all the time!!\""] = "\"Tất cả lửa, mọi lúc !!\""
    textfix["\"All it takes is a spark of genius.\""] = "\"Tất cả những gì nó cần là một tia sáng của thiên tài.\""
    textfix["\"All the wörld's a stage. För me!\""] = "\"Tất cả thế giới là một sân khấu. Cho tôi!\""
    textfix["\"All those who oppose me shall perish!\""] = "\"Tất cả những người phản đối tôi sẽ bị diệt vong!\""
    textfix["\"All will bathe in the prettiest of flames.\""] = "\"Tất cả sẽ tắm trong ngọn lửa đẹp nhất.\""
    textfix["\"All... will rot...\""] = "\"Tất cả ... sẽ thối rữa ...\""
    textfix["\"Alouette, je te plumerai.\""] = "\"Alouette, je te Plumerai.\""
    textfix["\"Alter is good. Alter shall not forsake us. Alter shall return.\""] = "\"Thay đổi là tốt. Thay đổi sẽ không bỏ rơi chúng ta. Thay đổi sẽ quay trở lại.\""
    textfix["\"Alter is our Champion. Alter is the Champion. The Champion is Alter.\""] = "\"Alter là Nhà vô địch của chúng tôi. Alter là Nhà vô địch. Nhà vô địch là Alter.\""
    textfix["\"Alter\"?"] = "\"Thay đổi\"?"
    textfix["\"Alter, Glorious Moon in the cold night sky. Cast your Life-giving Light on us forever.\""] = "\"Hãy thay đổi, Mặt trăng vinh quang trên bầu trời đêm lạnh giá. Hãy chiếu Ánh sáng ban sự sống của bạn mãi mãi cho chúng tôi.\""
    textfix["\"Always hold the board steady. Remember, a sharp knife is safer than a dull one.\nDon't forget.\""] = "\"Luôn giữ vững tấm bảng. Hãy nhớ rằng, một con dao sắc sẽ an toàn hơn một con dao cùn.\nĐừng quên.\""
    textfix["\"Am poison, no eat!\""] = "\"AM Poison, không ăn!\""
    textfix["\"Am sugarplum fairy, florp. Gimme plums!\""] = "\"Am Sugarplum Fairy, Phờ lọp. Gimme Plums!\""
    textfix["\"An air of mystery is the secret ingredient for any good soiree.\""] = "\"Không khí bí ẩn là thành phần bí mật cho bất kỳ buổi dạ hội hấp dẫn nào.\""
    textfix["\"And don't come back.\""] = "\"Và đừng quay lại.\""
    textfix["\"And just a dash of sweet rosewater.\""] = "\"Và chỉ là một chút nước hoa hồng ngọt ngào.\""
    textfix["\"And your hair has become very white;"] = "\"Và tóc của bạn đã trở nên rất trắng;"
    textfix["\"Anything can be fixed with hard work and elbow grease.\""] = "\"Việc gì cũng có thể giải quyết được bằng sự chăm chỉ và dầu mỡ.\""
    textfix["\"Applause röars as red, red röses flööd my stage!\""] = "\"Vỗ tay vang dội khi màu đỏ, hoa hồng đỏ tràn ngập sân khấu của tôi!\""
    textfix["\"April showers bring May flowers.\""] = "\"Vòi hoa sen mang hoa tháng năm.\""
    textfix["\"As usual, the responsibility of organizing the seasonal festivities falls to me.\""] = "\"Như thường lệ, trách nhiệm tổ chức các lễ hội theo mùa thuộc về tôi.\""
    textfix["\"Ashes, ashes, we all fall down.\""] = "\"Tro tàn, tro tàn, chúng ta đều rơi xuống.\""
    textfix["\"At times we sacrifice, at times we're sacrificed.\""] = "\"Có lúc chúng ta hy sinh, có lúc chúng ta hy sinh.\""
    textfix["\"Authored by C.W.\""] = "\"Tác giả của C.W.\""
    textfix["\"BOW BEFORE ME, FLESHLINGS!\""] = "\"CÚI ĐẦU TRƯỚC TA, LŨ THỊT DA!\""
    textfix["\"Baaaah\" yourself!"] = "Kêu \"baaaaaah\" như lũ ngu!"
    textfix["\"Behöld Mani's chösen warriör!\""] = "\"Beh  ld Mani's Ch  sen Warri  r!\""
    textfix["\"Beware.\" Beware of what?"] = "\"Cẩn thận.\" Coi chừng những gì?"
    textfix["\"Blast this heat! Where's a nice, chilled drink when you need it?\" -M"] = "\"Hãy xua tan cái nóng này! Đâu có đồ uống mát lạnh khi bạn cần?\" -M"
    textfix["\"Blue\" is an odd adjective for a flavor, but I can't disagree."] = "\"Xanh\" là một tính từ kỳ quặc để chỉ một hương vị, nhưng tôi không thể không đồng ý."
    textfix["\"Bound together are these chambers, yet in ways unnatural, wrought to confound all who enter.\""] = "\"Những gian phòng này được liên kết với nhau, nhưng theo cách phi tự nhiên, được tạo ra để khiến mọi kẻ bước vào phải bối rối.\""
    textfix["\"Brought to you by the Heralds of Tenebrau.\""] = "\"Được mang đến bởi Sứ Giả của Tenebrau.\""
    textfix["\"Brrr... it's a good thing you already have your own winter coat, Woby!\""] = "\"Brrr...thật may là bạn đã có áo khoác mùa đông cho riêng mình, Woby!\""
    textfix["\"By Hel's fire\" is a turn of phrase, dear."] = "\"By Hel's fire\" là một cách đổi cụm từ, em yêu."
    textfix["\"By the pricking of my thumbs, something wicked this way comes!\""] = "\"Bằng cách chích ngón tay cái của tôi, một cái gì đó độc ác sẽ đến!\""
    textfix["\"CRACKING WALNUT CODE\""] = "\"Cracking mã quả óc chó\""
    textfix["\"Call förth the höwling winds and biting cöld, the jötnar fear them nöt!\""] = "\"Hãy gọi những cơn gió gào thét và cái lạnh thấu xương, jötnar không sợ chúng!\""
    textfix["\"Cargo\" is sailor-lingo for \"stuff\"."] = "\"Hàng hóa\" là thuật ngữ của thủy thủ để chỉ \"đồ vật\"."
    textfix["\"Cave lonely\""] = "\"Cave Lonely\""
    textfix["\"Ch-chilly...\""] = "\"Ch-Chilly ...\""
    textfix["\"Charmed, I'm sure.\""] = "\"Charmed, tôi chắc chắn.\""
    textfix["\"Cold does not bother Wolfgang!\""] = "\"Lạnh không làm phiền Wolfgang!\""
    textfix["\"Combat is all about technique, dear.\""] = "\"Chiến đấu là tất cả về kỹ thuật, thân yêu.\""
    textfix["\"Come closer - we are hungry!\""] = "\"Đến gần hơn - chúng ta đói!\""
    textfix["\"Come closer... won't bite! (Hee-hee...)\""] = "\"Đến gần hơn ... sẽ không cắn! (Hee-hee ...)\""
    textfix["\"Come on Woby, that Winter's Feast tree won't decorate itself!\""] = "\"Thôi nào Woby, cây bữa tiệc mùa đông đó sẽ không tự trang trí!\""
    textfix["\"Come on. Give it your best shot.\""] = "\"Thôi nào. Hãy cho nó bức ảnh tốt nhất của bạn.\""
    textfix["\"Come onnnn, let me fire the cannon!\""] = "\"Hãy đến, hãy để tôi bắn đại bác!\""
    textfix["\"Could've sworn I saw one of the trees movin' when I was out choppin' firewood... must've been a trick of the light.\" -W"] = "\"Có thể thề rằng tôi đã nhìn thấy một trong những cái cây chuyển động khi tôi ra ngoài chặt củi... chắc chắn là do ánh sáng đánh lừa.\" -W"
    textfix["\"Dainty rose make Wolfgang strong, cultured man.\""] = "\"Bông hồng xinh xắn làm nên người đàn ông mạnh mẽ, có văn hóa của Wolfgang.\""
    textfix["\"Death, a necessary end, will come when it will come,\" but not today, my allies!"] = "\"Cái chết, một sự kết thúc cần thiết, sẽ đến khi nó đến,\" nhưng không phải hôm nay, các đồng minh của tôi!"
    textfix["\"Do not challenge the Mighty Wolfgang!\""] = "\"Đừng thách thức Wolfgang hùng mạnh!\""
    textfix["\"Do you believe in fairies? If you believe, clap your hands.\""] = "\"Bạn có tin vào các nàng tiên không? Nếu bạn tin, hãy vỗ tay.\""
    textfix["\"Do you ever feel adrift like a vessel without mooring?\""] = "\"Bạn có bao giờ cảm thấy trôi dạt như một con tàu không neo đậu không?\""
    textfix["\"Don't be silly, it's only a bad dream...\""] = "\"Đừng ngớ ngẩn, đó chỉ là một giấc mơ tồi tệ ...\""
    textfix["\"Don't even think about it.\""] = "\"Đừng nghĩ về nó.\""
    textfix["\"Don't get between me and my hoard of souls.\""] = "\"Đừng có được giữa tôi và tích trữ linh hồn của tôi.\""
    textfix["\"Don't mess with us.\""] = "\"Đừng gây rối với chúng tôi.\""
    textfix["\"Don't play with matches.\""] = "\\ \"Đừng chơi với các trận đấu. \""
    textfix["\"Don't slip up or you might get a face full of snow, hyuyu!\""] = "\"Đừng trượt chân nếu không mặt bạn sẽ đầy tuyết đấy, hyuyu!\""
    textfix["\"Don't start a tussle you can't finish.\""] = "\"Đừng bắt đầu một cuộc tranh đấu mà bạn không thể hoàn thành.\""
    textfix["\"Don't worry Sirs and Madams, Woby and I are on the case!\""] = "\"Xin đừng lo lắng, thưa ông bà, Woby và tôi đang phụ trách vụ án!\""
    textfix["\"Dread twisted into devotion. Trembling into gratitude.\""] = "\"Nỗi sợ hãi biến thành sự tận tâm. Run rẩy thành lòng biết ơn.\""
    textfix["\"Dressing up not so bad sometimes.\""] = "\"Mặc quần áo không quá tệ.\""
    textfix["\"EMPATHY MODULE NOT RESPONDING\""] = "\"BỘ PHẬN CẢM XÚC KHÔNG CÓ PHẢN HỒI\""
    textfix["\"Eternal\"? Ha!"] = "Mãi mãi? Ha!"
    textfix["\"Even I let my hair down occasionally.\""] = "\"Thậm chí tôi thỉnh thoảng để tóc xuống.\""
    textfix["\"Even the most majestic tree's gotta start as a seed.\""] = "\"Ngay cả cái cây hùng vĩ nhất cũng phải bắt đầu từ hạt giống.\""
    textfix["\"Every meal ends in an empty plate.\""] = "\"Mỗi bữa ăn kết thúc trong một đĩa trống.\""
    textfix["\"Every story needs a fearless adventurer and their trusty steed!\""] = "\"Mọi câu chuyện đều cần một nhà thám hiểm dũng cảm và chiến mã đáng tin cậy của họ!\""
    textfix["\"Everything I make is magnificent.\""] = "\"Mọi thứ tôi làm là tuyệt vời.\""
    textfix["\"Extra, extra! Read all about it!\""] = "\"Thêm, thêm, đọc tất cả về nó!\""
    textfix["\"Eye\" like it!"] = "\"Mắt\" thích đấy!"
    textfix["\"Fancy a matchstick, sir?\""] = "\"Fancy một que diêm, thưa ngài?\""
    textfix["\"Feel big fancy\""] = "\"Cảm thấy to lạ mắt\""
    textfix["\"Feel pretty\""] = "\"Cảm thấy xinh đẹp\""
    textfix["\"Field botany isn't my specialty... but it's growing on me.\""] = "\"Thực vật học trên đồng ruộng không phải là chuyên môn của tôi... nhưng nó đang phát triển trong tôi.\""
    textfix["\"Five more minutes.\""] = "\"Năm phút nữa.\""
    textfix["\"Follow me into the forest deep, where impish sorts frolic and play!\""] = "\"Theo tôi vào sâu trong rừng, nơi lũ tinh quái nô đùa và nô đùa!\""
    textfix["\"Follow the instructions\", mum always said."] = "\"Hãy làm theo hướng dẫn\", mẹ luôn nói."
    textfix["\"For dark is become our shield. Our sustenance. Our solace.\""] = "\"Vì bóng tối đã trở thành lá chắn của chúng ta. Nguồn sống của chúng ta. Niềm an ủi của chúng ta.\""
    textfix["\"Forests are full of shadows, eh?\""] = "\"Rừng đầy bóng, hả?\""
    textfix["\"Forsaken wretches of the one who turned away.\""] = "\"Những kẻ khốn nạn bị bỏ rơi.\""
    textfix["\"Freedom suits me.\""] = "\"Tự do phù hợp với tôi.\""
    textfix["\"Freeing him might not have been my best idea.\""] = "\"Trả tự do cho anh ta có lẽ không phải là ý tưởng hay nhất của tôi.\""
    textfix["\"Frilly and gilly, florp!\""] = "\"Frilly và Gilly, Phờ lọp!\""
    textfix["\"From desolation were we drawn. Into the veiled embrace of Them.\""] = "\"Chúng ta đã bị lôi kéo khỏi sự hoang tàn. Vào trong vòng tay che đậy của Họ.\""
    textfix["\"From time to time I've spotted bottles bobbing along the ocean currents, just out of reach from the shore. I have half a mind to construct a boat and retrieve one of them... I have a gut feeling that someone is trying to send out a message.\" -W"] = "\"Thỉnh thoảng tôi nhìn thấy những cái chai bồng bềnh dọc theo dòng hải lưu, ngay ngoài tầm với của bờ biển. Tôi có ý định đóng một chiếc thuyền và lấy một trong số chúng... Tôi có linh cảm rằng ai đó đang cố gắng gửi một tin nhắn.\" -W"
    textfix["\"Glurgh, no call me shrimp! Me big scary pirate!!\""] = "\"Glurgh, không gọi tôi là tôm! Tôi là cướp biển đáng sợ lớn !!\""
    textfix["\"Golden fields of hay, ripe for burning... I mean harvesting.\""] = "\"Những cánh đồng cỏ khô vàng, chín để đốt... Ý tôi là đang thu hoạch.\""
    textfix["\"Goodness gracious, it seems you've been annihilated.\""] = "\"Lòng tốt duyên dáng, có vẻ như bạn đã bị tiêu diệt.\""
    textfix["\"Grrrr... We're scary!\""] = "\"Grrrr ... chúng tôi đáng sợ!\""
    textfix["\"Gööd tidings to all!\""] = "\"G    d cho tất cả mọi người!\""
    textfix["\"Ha ha! Did I scare ya?\""] = "\"Ha ha! Tôi có sợ bạn không?\""
    textfix["\"Have you found your treasure yet? When you do, will you come home?\""] = "\"Bạn đã tìm thấy kho báu của mình chưa? Khi tìm được, bạn sẽ về nhà chứ?\""
    textfix["\"He died before getting to see these beautiful flames.\""] = "\"Anh ấy đã chết trước khi nhìn thấy những ngọn lửa tuyệt đẹp này.\""
    textfix["\"Heh heh, this thing's itchy.\""] = "\"Heh heh, thứ này là ngứa.\""
    textfix["\"Hello friend?\""] = "\"Xin chào bạn?\""
    textfix["\"Herbal\" therapy."] = "Liệu pháp 'thảo dược'."
    textfix["\"Here lies some gal.\""] = "\"Đây là một số gal.\""
    textfix["\"Here lies some guy.\""] = "\"Đây là một số chàng trai.\""
    textfix["\"Here lies some person.\""] = "\"Đây là một số người.\""
    textfix["\"Here much long... much long\""] = "\"Ở đây lâu quá... lâu quá\""
    textfix["\"Hmph. It's cold out.\""] = "\"HMPH. Trời lạnh.\""
    textfix["\"Hmph.\""] = "\"HMPH.\""
    textfix["\"Honest work makes an honest woman.\""] = "\"Công việc trung thực làm cho một người phụ nữ trung thực.\""
    textfix["\"Honest work will only get ya so far.\""] = "\"Công việc trung thực sẽ chỉ nhận được YA cho đến nay.\""
    textfix["\"Honestly, a working knowledge of medicinal botany is hardly witchcraft!\""] = "\"Thành thật mà nói, kiến thức thực tế về dược liệu khó có thể coi là phép thuật phù thủy!\""
    textfix["\"Hope I don't burn the trees.\""] = "\"Hy vọng tôi không đốt cây.\""
    textfix["\"Hot bath sound nice...\""] = "\"Nghe có vẻ tốt đẹp ...\""
    textfix["\"Hug?\""] = "\"Ôm?\""
    textfix["\"I AM THE FUTURE\""] = "\"Tôi là tương lai\""
    textfix["\"I AM THE GOLD STANDARD\""] = "\"TÔI LÀ TIÊU CHUẨN VÀNG\""
    textfix["\"I AM THE ROOT OF ALL EVIL\""] = "\"TÔI LÀ NGUỒN GỐC CỦA TẤT CẢ MỌI ĐIỀU XẤU\""
    textfix["\"I POLISHED MY CHASSIS FOR THE OCCASION\""] = "\"Tôi đã đánh bóng khung gầm của mình cho dịp này\""
    textfix["\"I actually just work in the galley.\""] = "\"Tôi thực sự chỉ làm việc trong galley.\""
    textfix["\"I ain't one to keep up with trends, but isn't this a bit old-fashioned?\""] = "\"Tôi không phải là người theo kịp xu hướng, nhưng chẳng phải điều này hơi lỗi thời sao?\""
    textfix["\"I am coming for you!\""] = "\"Tôi đang đến với bạn!\""
    textfix["\"I am feeling the chemistry!\""] = "\"Tôi đang cảm nhận được chất hóa học!\""
    textfix["\"I am in deepest mourning...\""] = "\"Tôi đang trong tình trạng thương tiếc sâu nhất ...\""
    textfix["\"I am mighty! No one is mightier!\""] = "\"Ta thật phi thường! Không kẻ nào có thể vĩ đại hơn!\""
    textfix["\"I am the best that ever was!!\""] = "\"Tôi là người giỏi nhất từng có !!\""
    textfix["\"I can handle myself.\""] = "\"Tôi có thể cải thiện bản thân.\""
    textfix["\"I can tough anything out.\""] = "\"Tôi có thể khó khăn với bất cứ điều gì.\""
    textfix["\"I carry on for Abigail's sake.\""] = "\"Tôi tiếp tục vì lợi ích của Abigail.\""
    textfix["\"I clean up pretty good, eh?\""] = "\"Tôi dọn dẹp khá tốt, hả?\""
    textfix["\"I could do with a haircut and a cup of tea, eh?\""] = "\"Tôi có thể làm với một kiểu tóc và một tách trà, hả?\""
    textfix["\"I couldn't have imagined it, I'm certain I just saw a piece of the moon break off and crash into the ocean! Perhaps my compatriots will join me in a search for it...\" -W"] = "\"Tôi không thể tưởng tượng nổi, tôi chắc chắn mình vừa nhìn thấy một mảnh trăng vỡ ra và rơi xuống biển! Có lẽ đồng bào của tôi sẽ cùng tôi đi tìm nó...\" -W"
    textfix["\"I cöuld take yöu curs with öne eye behind my mask!\""] = "\"Tôi có thể nhận những lời chửi rủa của bạn chỉ bằng một con mắt đằng sau chiếc mặt nạ của tôi!\""
    textfix["\"I delight in an elegant soirée, provided it concludes at a sensible hour.\""] = "\"Tôi thích thú với một buổi dạ hội sang trọng, miễn là nó kết thúc vào một giờ hợp lý.\""
    textfix["\"I didn't do it. Really.\""] = "\"Tôi đã không làm điều đó. Thực sự.\""
    textfix["\"I didn't like it here anyway.\""] = "\"Dù sao thì tôi cũng không thích nó ở đây.\""
    textfix["\"I don't break down easy.\""] = "\"Tôi không phá vỡ dễ dàng.\""
    textfix["\"I don't need a handbook telling me what to do - I make the rules now!\""] = "\"Tôi không cần một cuốn sổ tay hướng dẫn tôi phải làm gì - tôi đưa ra các quy tắc ngay bây giờ!\""
    textfix["\"I experimented with making a rudimentary compass and discovered that this place does in fact seem to have a magnetic North. Curiously, it also pointed out the positions of my fellow camp mates who, as it turned out, had already crafted similar compasses of their own.\" -W"] = "\"Tôi đã thử nghiệm chế tạo một chiếc la bàn thô sơ và phát hiện ra rằng nơi này trên thực tế dường như có một cực Bắc từ tính. Thật kỳ lạ, nó cũng chỉ ra vị trí của những người bạn cùng trại của tôi, những người hóa ra đã chế tạo ra những chiếc la bàn tương tự của riêng họ.\" -W"
    textfix["\"I fear I may no longer be able to trust my own eyes. I've been catching glimpses of strange shadowy forms at the edges of my vision with increasing frequency... surely they can't really be there?\" -W"] = "\"Tôi sợ rằng tôi có thể không còn tin vào mắt mình nữa. Tôi đã nhìn thấy những hình bóng kỳ lạ ở rìa tầm nhìn của mình với tần suất ngày càng tăng... chắc chắn chúng thực sự không thể ở đó?\" -W"
    textfix["\"I fear nöt Surtr's flames!\""] = "\"Tôi sợ ngọn lửa của Surtr!\""
    textfix["\"I feared it might injure the brain;"] = "\"Tôi sợ nó có thể gây thương tích cho não;"
    textfix["\"I finally worked up the courage to explore the underground caverns. To my surprise, I found there was ample light provided by a most curious glowing plant that seems to grow naturally throughout the cave system. I've harvested some bulbs for further study.\" -W"] = "\"Cuối cùng tôi đã lấy hết can đảm để khám phá các hang động dưới lòng đất. Thật ngạc nhiên, tôi thấy có rất nhiều ánh sáng được cung cấp bởi một loại cây phát sáng kỳ lạ nhất dường như mọc tự nhiên khắp hệ thống hang động. Tôi đã thu hoạch một số củ để nghiên cứu thêm.\" -W"
    textfix["\"I find myself returning more and more frequently to my magnificent science machine, busying myself with prototyping new tools to aid in our survival. After all, I must do something to keep myself sane in this strange place...\" -W"] = "\"Tôi thấy mình ngày càng quay trở lại với cỗ máy khoa học tuyệt vời của mình, bận rộn với việc tạo ra các công cụ mới để hỗ trợ sự sống còn của chúng ta. Sau cùng, tôi phải làm gì đó để giữ cho mình tỉnh táo ở nơi xa lạ này...\" -W"
    textfix["\"I grow, untamed and untended.\""] = "\"Tôi phát triển, chưa được khám phá và chưa được kiểm soát.\""
    textfix["\"I hate parties.\""] = "\"Tôi ghét tiệc tùng.\""
    textfix["\"I have an urge to dance around a fire in the moonlight.\""] = "“Tôi muốn nhảy múa quanh đống lửa dưới ánh trăng.”"
    textfix["\"I hope I don't break my glasses.\""] = "\"Tôi hy vọng tôi không làm vỡ kính của tôi.\""
    textfix["\"I hope I don't lose any points for the state of my uniform.\""] = "\"Tôi hy vọng mình không bị mất điểm vì tình trạng đồng phục của mình.\""
    textfix["\"I just need to find my beautiful assistant.\""] = "\"Tôi chỉ cần tìm trợ lý xinh đẹp của mình.\""
    textfix["\"I know you're still out there, my dear. I won't ever give up.\""] = "\"Tôi biết bạn vẫn ở ngoài đó, em yêu. Tôi sẽ không bao giờ từ bỏ.\""
    textfix["\"I know you're still there, Abigail... we'll be able to play together again soon.\""] = "\"Tôi biết bạn vẫn còn ở đó, Abigail... chúng ta sẽ sớm chơi lại với nhau thôi.\""
    textfix["\"I let in darkness once before, what's the harm in a little more?\""] = "\"Ta đã từng để bóng tối vào rồi, thêm một chút nữa thì có hại gì?\""
    textfix["\"I must train for the races!\""] = "\"Tôi phải đào tạo cho các cuộc đua!\""
    textfix["\"I never was one to shy away from theatrics, or a good suit.\""] = "\"Tôi chưa bao giờ là người ngại sân khấu hay một bộ đồ đẹp.\""
    textfix["\"I often look from the highest hill, that I might see my boatman...\""] = "\"Tôi thường nhìn từ ngọn đồi cao nhất để có thể nhìn thấy người chèo thuyền của mình...\""
    textfix["\"I only cook with natural ingredients.\""] = "\"Tôi chỉ nấu ăn với các thành phần tự nhiên.\""
    textfix["\"I seem to have developed quite a taste for treasure.\""] = "\"Tôi dường như đã phát triển khá một hương vị cho kho báu.\""
    textfix["\"I shall fight för the förest!\""] = "\"Tôi sẽ chiến đấu vì rừng xanh\""
    textfix["\"I shall scare öff all the black winged beasties!\""] = "\"Tôi sẽ sợ tất cả các con thú có cánh đen!\""
    textfix["\"I still have the last gift you gave me. \"A pearl for Pearl\"... remember?\""] = "\"Tôi vẫn còn món quà cuối cùng bạn tặng tôi. \"Một viên ngọc trai\"... nhớ chứ?\""
    textfix["\"I stumbled upon a rather suspicious mound of dirt... perhaps it was left by a creature of some sort? This may require further investigation...\" -W"] = "\"Tôi tình cờ thấy một ụ đất khá đáng ngờ... có lẽ nó bị một loại sinh vật nào đó để lại? Điều này có thể cần phải điều tra thêm...\" -W"
    textfix["\"I suppose I should make time to stop and smell the roses every so often.\""] = "\"Tôi cho rằng thỉnh thoảng tôi nên dành thời gian để dừng lại và ngửi mùi hoa hồng.\""
    textfix["\"I take no pleasure in this.\""] = "\"Tôi không có niềm vui trong việc này.\""
    textfix["\"I think I really rose to the occasion! Eh, Woby?\""] = "\"Tôi nghĩ tôi đã thực sự bắt kịp thời cơ! Ơ, Woby?\""
    textfix["\"I used my special moustache wax.\""] = "\"Tôi đã sử dụng sáp ria mép đặc biệt của mình.\""
    textfix["\"I want to go home, but we can't find the way.\""] = "\"Tôi muốn về nhà, nhưng chúng tôi không thể tìm thấy con đường.\""
    textfix["\"I will deströy my enemies!\""] = "\"Tôi sẽ phá hủy kẻ thù của tôi!\""
    textfix["\"I will try to summon up some holiday spirit... if I must.\""] = "\"Tôi sẽ cố gắng khơi dậy tinh thần ngày lễ... nếu phải.\""
    textfix["\"I wonder if Maman missed my holiday baking.\""] = "\"Tôi tự hỏi liệu mẹ tôi có bỏ lỡ dịp nướng bánh trong kỳ nghỉ của tôi không.\""
    textfix["\"I yearn för my chance ön the pröving gröunds!\""] = "\"Tôi khao khát cơ hội của tôi"
    textfix["\"I'd say this look is best served cold.\""] = "\"Tôi muốn nói cái nhìn này được phục vụ tốt nhất.\""
    textfix["\"I'd wear it more often, but it's so heavy with all these badges...\""] = "\"Tôi sẽ đeo nó thường xuyên hơn, nhưng nó quá nặng với những huy hiệu này...\""
    textfix["\"I'll conquer this world with the power of my MIND!\""] = "\"Tôi sẽ chinh phục thế giới này bằng sức mạnh của LÍ TRÍ của tôi!\""
    textfix["\"I'll keep sending messages, until one reaches you...\""] = "\"Tôi sẽ tiếp tục gửi tin nhắn cho đến khi có tin nhắn đến được với bạn...\""
    textfix["\"I'll only go to the party if Abigail comes too.\""] = "\"Tôi sẽ chỉ đi dự tiệc nếu Abigail cũng đến.\""
    textfix["\"I'm absolutely adorable!\""] = "\"Tôi thực sự đáng yêu!\""
    textfix["\"I'm on a see-food diet.\""] = "\"Tôi đang ăn kiêng.\""
    textfix["\"I'm simply tickled pink, hyuyu!\""] = "\"Tôi chỉ thấy nhột nhột thôi, hyuyu!\""
    textfix["\"I'm sure I had a scientific reason for this.\""] = "\"Tôi chắc chắn tôi đã có một lý do khoa học cho điều này.\""
    textfix["\"I'm thinking of opening a chocolate factory.\""] = "\"Tôi đang nghĩ đến việc mở một nhà máy sô cô la.\""
    textfix["\"I'm waiting for you. At the spot where we first met. I've been waiting so long...\""] = "\"Anh đang đợi em. Tại nơi chúng ta lần đầu gặp nhau. Anh đã đợi rất lâu rồi...\""
    textfix["\"I've been in scraps before, eh?\""] = "\"Tôi đã ở trong phế liệu trước đây, hả?\""
    textfix["\"I've been told, my blood can run cold!\""] = "\"Tôi đã được bảo rồi, máu của tôi có thể nguội lạnh!\""
    textfix["\"I've better places to be.\""] = "\"Tôi đã có nơi tốt hơn để được.\""
    textfix["\"I've cooked up something frightful, just for you!\""] = "\"Tôi đã nấu một thứ gì đó đáng sợ, chỉ dành cho bạn!\""
    textfix["\"I've discovered a lot of things at sea... that I'm prone to seasickness, for one.\""] = "\"Tôi đã phát hiện ra rất nhiều điều trên biển... chẳng hạn như tôi dễ bị say sóng.\""
    textfix["\"I've faced worse ordeals.\""] = "\"Tôi đã phải đối mặt với những thử thách tồi tệ hơn.\""
    textfix["\"I've finally perfected my design for an ingenious (if I do say so myself) device that stores important garden-based knowledge. Certain naysayers might point out that it looks like nothing more than an overturned flowerpot worn on the head... some people simply don't have an eye for science.\" -W"] = "\"Cuối cùng tôi đã hoàn thiện thiết kế của mình cho một thiết bị khéo léo (nếu tôi nói như vậy) để lưu trữ những kiến thức quan trọng về làm vườn. Một số người phản đối có thể chỉ ra rằng nó trông chẳng khác gì một lọ hoa lật úp đội trên đầu... một số người đơn giản là không có con mắt khoa học.\" -W"
    textfix["\"I've harnessed the power of the earth's core!\""] = "\"Tôi đã khai thác sức mạnh của lõi trái đất!\""
    textfix["\"I've the brains AND the brawn.\""] = "\"Tôi có bộ não VÀ cơ bắp.\""
    textfix["\"IF I HAD A HEART IT WOULD BE MADE OF ICE\""] = "\"Nếu tôi có một trái tim thì nó sẽ được làm bằng băng\""
    textfix["\"If Lucy's the belle of the ball, I guess that makes me the beast.\""] = "\"Nếu Lucy là người đẹp nhất trong vũ hội, tôi đoán điều đó khiến tôi trở thành quái vật.\""
    textfix["\"If you fight us, you will lose.\""] = "\"Nếu bạn chiến đấu với chúng tôi, bạn sẽ thua.\""
    textfix["\"In my youth,\" Father William replied to his son,"] = "\"Khi còn trẻ,\" Cha William trả lời con trai mình,"
    textfix["\"Into woods, follow!\""] = "\"Vào rừng, làm theo!\""
    textfix["\"It called bye-oh-loomy...loominess...loomin-essence... GLOWY!\""] = "\"Nó gọi là bye-oh-loomy...loominess...loomin-essence... GLOWY!\""
    textfix["\"It seems that every time we discover a doorway out of this terrible place, it just leads to more strange worlds with new horrors to endure. Still, I can't give up hope that one day we'll find a doorway that will take us home...\" -W"] = "\"Dường như mỗi lần chúng ta khám phá ra một cánh cửa thoát khỏi nơi khủng khiếp này, nó lại dẫn đến những thế giới kỳ lạ hơn với những nỗi kinh hoàng mới phải chịu đựng. Tuy nhiên, tôi vẫn không thể từ bỏ hy vọng rằng một ngày nào đó chúng ta sẽ tìm thấy một cánh cửa đưa chúng ta về nhà...\" -W"
    textfix["\"It takes a lot of lumber to keep a boat ship-shape, eh?\""] = "\"Phải mất rất nhiều gỗ để giữ một chiếc thuyền có hình con tàu, hả?\""
    textfix["\"It turns out that Koalefants are a bit hardier than I expected. I (quite sensibly) decided to take a... strategic retreat until I'm better prepared.\" -W"] = "\"Hóa ra Koalefants cứng hơn tôi mong đợi một chút. Tôi (khá hợp lý) đã quyết định ... rút lui chiến lược cho đến khi tôi chuẩn bị tốt hơn.\" -W"
    textfix["\"It's a fine day for some fine dining, non?\""] = "\"Đó là một ngày tốt cho một số bữa ăn ngon, không?\""
    textfix["\"It's a nice view from the top.\""] = "\"Đó là một cái nhìn tốt đẹp từ đầu.\""
    textfix["\"It's almost time\"? Time for what?"] = "\"Đã đến lúc rồi\"? Để làm moé gì?"
    textfix["\"It's dirty down here.\""] = "\"Nó bẩn ở đây.\""
    textfix["\"It's good that we know how to make silk, our claws keep catching on the sail...\""] = "\"Thật tốt khi chúng ta biết dệt lụa, móng vuốt của chúng ta cứ bám vào cánh buồm...\""
    textfix["\"It's not as bad as it looks.\""] = "\"Nó không tệ như nó có vẻ.\""
    textfix["\"It's the best game you can name!\""] = "\"Đó là trò chơi hay nhất bạn có thể đặt tên!\""
    textfix["\"It's the perfect time of year for sitting in front of a roaring fire.\""] = "\"Đó là thời điểm hoàn hảo trong năm để ngồi trước ngọn lửa đang bùng cháy.\""
    textfix["\"It's worse than it looks.\""] = "\"Nó tệ hơn vẻ ngoài của nó.\""
    textfix["\"Just follow the recipe, dear.\""] = "\"Chỉ cần làm theo công thức, thân yêu.\""
    textfix["\"Just needed a rest.\""] = "\"Chỉ cần nghỉ ngơi thôi.\""
    textfix["\"Knowledge is power!\""] = "\"Kiên thức là sức mạnh!\""
    textfix["\"Last time I baited my hook with berries I caught more fish than I could carry, but when I tried today? Barely a nibble! Guess the berry trick only works on some of 'em.\" -W"] = "\"Lần trước tôi dùng quả mọng để mồi lưỡi câu, tôi đã bắt được nhiều cá hơn mức tôi có thể mang theo, nhưng khi tôi thử hôm nay? Chỉ là một miếng thôi! Đoán là thủ thuật quả mọng chỉ có tác dụng với một số trong số chúng.\" -W"
    textfix["\"Let ol'Winnie fix ya up somethin' special.\""] = "\"Hãy để ol'winnie sửa chữa bạn đặc biệt.\""
    textfix["\"Let the cursed Keystone never cross this threshold.\""] = "\"Hãy để Keystone bị nguyền rủa không bao giờ vượt qua ngưỡng này.\""
    textfix["\"Let the pursuit of knowledge stretch beyond every horizon.\""] = "\"Hãy để việc theo đuổi kiến thức vượt ra ngoài mọi chân trời.\""
    textfix["\"Let this be the party tö end all parties!\""] = "\"Hãy coi đây là bữa tiệc kết thúc mọi bữa tiệc!\""
    textfix["\"Let us remember the days öf öld!\""] = "\"Chúng ta hãy nhớ về những ngày xưa!\""
    textfix["\"Let's get cooking!\""] = "\"Chúng ta hãy cùng nấu ăn nào!\""
    textfix["\"Look out evildoers, I've got the moon on my side!\""] = "\"Nhìn ra những kẻ bất lương, tôi đã có mặt trăng ở bên cạnh!\""
    textfix["\"Look, we lost a tooth!\""] = "\"Hãy nhìn xem, chúng tôi bị mất một chiếc răng!\""
    textfix["\"Loyalty unending. We kneel before the undying. The unaltering.\""] = "\"Lòng trung thành bất tận. Chúng tôi quỳ gối trước sự bất diệt. Sự không thay đổi.\""
    textfix["\"Lucy is my sous chef.\""] = "\"Lucy là đầu bếp sous của tôi.\""
    textfix["\"Lucy\" was it? Oh botheration, now he's got ME talking to it!"] = "\"Lucy\" phải không? Ôi phiền thật, giờ anh ấy bắt TÔI phải nói chuyện với nó!"
    textfix["\"MEAL SERVER DOWN\""] = "\"MÁY CHỦ MEAL NGỪNG HOẠT ĐỘNG\""
    textfix["\"MEEEEEAT.\""] = "\"Meeeeeat.\""
    textfix["\"MOTIVATIONAL SPEAKING\""] = "\"Nói một cách động lực\""
    textfix["\"Magic is merely science that hasn't been categorized yet.\""] = "\"Phép thuật chỉ là khoa học chưa được phân loại.\""
    textfix["\"Manners, my dear.\""] = "\"Cách cư xử, thân yêu của tôi.\""
    textfix["\"Maybe fluff okay for wintertime, but scales better all other times!\""] = "\"Có thể lông tơ sẽ ổn vào mùa đông, nhưng sẽ cân đối hơn vào những thời điểm khác!\""
    textfix["\"Maybe if I dress like them, they won't sting me!\""] = "\"Có lẽ nếu tôi ăn mặc như họ, họ sẽ không đâm tôi!\""
    textfix["\"Me feel fancy, florp!\""] = "\"Tôi thấy lạ quá, phờ lốp!\""
    textfix["\"Me look radiant on moonlit swim.\""] = "\"Tôi trông rạng rỡ khi bơi dưới ánh trăng.\""
    textfix["\"Me ready fight dirty.\""] = "\"Tôi sẵn sàng chiến đấu bẩn thỉu.\""
    textfix["\"Me scary dragon! Gonna gobble up all the princesses, hee-hee!\""] = "\"Tôi là con rồng đáng sợ! Sẽ nuốt chửng tất cả các công chúa, hee-hee!\""
    textfix["\"Mermfolk Ownlee\"... hmph. How childish."] = "\"Người Cá Ownlee\"... hmph. Thật trẻ con làm sao."
    textfix["\"Mermfolk Ownlee\"? Hm. I see more spelling lessons are in order."] = "\"Chỉ dành cho người cá Merm\"? Hm. Tôi nghĩ cần thêm vài bài học chính tả."
    textfix["\"Mermfolk ancestors definitely look like this, florp!\""] = "\"Tổ tiên của người cá chắc chắn trông như thế này, florp!\""
    textfix["\"Mermfolk known for hos-per-tality, florp.\""] = "\"Nàng tiên cá được biết đến với lòng-mến-khách, florp.\""
    textfix["\"Mightiest Wolfgang is no heel!\""] = "\"Wolfgang mạnh nhất là không có gót!\""
    textfix["\"Mighty Alter, the source of our strength, our sole provider. We are loyal to none but You.\""] = "\"Mighty Alter, nguồn sức mạnh của chúng tôi, nhà cung cấp duy nhất của chúng tôi. Chúng tôi không trung thành với ai ngoài Bạn.\""
    textfix["\"Mighty Wolfgang cannot wait to step into ring!\""] = "\"Mighty Wolfgang không thể chờ đợi để bước vào vòng!\""
    textfix["\"Milk. Eggs. Bacon.\""] = "\"Sữa. Trứng. Bacon.\""
    textfix["\"Moon\" Figure"] = "Tượng \"Mặt Trăng\""
    textfix["\"Moon\" Figure Sketch"] = "Bản Thảo Tượng \"Mặt Trăng\""
    textfix["\"Moon\" Sketch"] = "Bản Phác Tượng Mặt Trăng"
    textfix["\"Moon\" detritus."] = "mảnh vụn \"Mặt trăng\"."
    textfix["\"Moon\" rock."] = "\"Đá mặt trăng."
    textfix["\"Much, much handsome\""] = "\"Nhiều, nhiều đẹp trai\""
    textfix["\"Murder\", she wrote."] = "\"Giết người\", cô viết."
    textfix["\"My food's always burned to perfection!\""] = "\"Thức ăn của tôi luôn bị cháy đến hoàn hảo!\""
    textfix["\"My future will reveal itself in the phases of the moon.\""] = "\"Tương lai của tôi sẽ tự lộ diện theo các tuần trăng.\""
    textfix["\"My name shall live ön förever, as the scöurge öf the seven seas!\""] = "\"Tên tôi sẽ sống   n f  rever, như sc  urge   f Seven Sea!\""
    textfix["\"My skill in battle is withöut peer.\""] = "\"Kỹ năng của tôi trong trận chiến là với  Ut.\""
    textfix["\"My volcanic smoke shall encase the world in darkness.\""] = "\"Khói núi lửa của tôi sẽ bao quanh thế giới trong bóng tối.\""
    textfix["\"NOW THE OUTSIDE MATCHES THE INSIDE. EVIL.\""] = "\"NGAY BÂY GIỜ BÊN NGOÀI BÊN TRONG. EVIL.\""
    textfix["\"Naughty. Definitely naughty.\""] = "\"Nghịch ngợm. Chắc chắn là nghịch ngợm.\""
    textfix["\"New grown from old\""] = "\"Mới phát triển từ cũ\""
    textfix["\"No beast withstandeth the will of one whose heart runneth wild.\""] = "\"Không con thú nào có thể chống lại ý chí của một kẻ có trái tim cuồng nhiệt.\""
    textfix["\"No longer doth the shadow stir terror within our hearts.\""] = "\"Bóng tối không còn khuấy động nỗi kinh hoàng trong trái tim chúng ta nữa.\""
    textfix["\"No! I'm the village GENIUS!\""] = "\"Không! Tôi là THIÊN TÀI của làng!\""
    textfix["\"Not enough people appreciate the minutiae of temporal tinkering.\""] = "\"Không đủ người đánh giá cao những chi tiết vụn vặt của việc mày mò tạm thời.\""
    textfix["\"Not from fairy story... from scary story!\""] = "\"không phải từ câu chuyện cổ tích ... từ câu chuyện đáng sợ!\""
    textfix["\"Not sick, just coffin.\""] = "\"Không bệnh, chỉ quan tài.\""
    textfix["\"Not yet mid-summer\", you say? Well my friend, the early bird gets the worm!"] = "\"Chưa đến giữa hè\", bạn nói? Bạn ơi, con chim sớm sẽ có sâu!"
    textfix["\"Nothing beats a golden croissant... I mean crescent.\""] = "\"Không gì có thể sánh bằng một chiếc bánh sừng bò vàng...ý tôi là hình lưỡi liềm.\""
    textfix["\"Nothing here is what it seems. If you're reading this, keep an eye on the rabbits, don't trust the statues, and don't mistake that thing hanging in the night sky for the moon...\" -W"] = "\"Có vẻ như không có gì ở đây cả. Nếu bạn đang đọc cái này, hãy để ý đến lũ thỏ, đừng tin vào những bức tượng và đừng nhầm thứ treo trên bầu trời đêm với mặt trăng...\" -W"
    textfix["\"Nothing is more fashionable than punctuality.\""] = "\"không có gì là thời trang hơn đúng giờ.\""
    textfix["\"Nothing personal pal, the ice industry's a cold business.\""] = "\"Không có gì đâu bạn ơi, ngành công nghiệp nước đá là một ngành kinh doanh lạnh lùng.\""
    textfix["\"Nothing worthwhile is ever done on an empty stomach!\""] = "\"Chắng có gì đáng để làm cho xong khi mà bụng đang đói!\""
    textfix["\"OVERCHARGED, READY TO CHARGE\""] = "\"QUÁ TUYỆT VỜI, SẴN SÀNG ĐỂ KIẾM TIỀN\""
    textfix["\"OVERGROWN. CIRCUITS BLOWN\""] = "\"TỔNG HỢP. QUẦN ÁO MÀU XANH\""
    textfix["\"Ode to the Scenery\""] = "\"Ode to the Mockery\""
    textfix["\"Oh botheration, where have I gotten myself this time?\""] = "\"Ồ làm phiền, lần này tôi đã lấy mình ở đâu?\""
    textfix["\"Oh dear, I have no idea where I'm going.\""] = "\"Ôi trời, tôi không biết mình sẽ đi đâu.\""
    textfix["\"Oh no, no!\" said the little fly"] = "\"Ồ không, không!\" nói con ruồi nhỏ"
    textfix["\"Oh yes, I'm cooking something up.\""] = "\"Ồ vâng, tôi đang nấu một cái gì đó lên.\""
    textfix["\"Ohh, my aching spines...\""] = "\"Ôi, đau nhức xương sống của tôi...\""
    textfix["\"Ol'Kramps did always say; if I kept making a funny face it'd get stuck that way.\""] = "\"Ol'Kramps luôn nói rằng nếu tôi cứ làm bộ mặt buồn cười thì mọi việc sẽ bế tắc như vậy.\""
    textfix["\"Ol'Kramps says my powers should grow in soon. Hyuyu!\""] = "\"Ol'kramp nói rằng sức mạnh của tôi sẽ sớm phát triển. Hyuyu!\""
    textfix["\"Once I've perfected a recipe, I find it helpful to write it down. Luckily, I've been able to cobble together a rough cookbook for just such a thing out of some spare pieces of parchment. Now my mind is free to worry about more immediate things...\" -W"] = "\"Khi tôi đã hoàn thiện một công thức nấu ăn, tôi thấy việc viết nó ra sẽ rất hữu ích. May mắn thay, tôi đã có thể soạn ra một cuốn sách dạy nấu ăn thô sơ cho một món như vậy chỉ từ vài mảnh giấy da thừa. Bây giờ tâm trí tôi có thể tự do lo lắng về những việc trước mắt hơn...\" -W"
    textfix["\"One must either offer a tribute, or become the tribute.\""] = "\"Người ta phải cống nạp hoặc trở thành cống nạp.\""
    textfix["\"One of the simplest ways to invite rain is to kill a-\" oh..."] = "\"Một trong những cách đơn giản nhất để mời mưa là giết-\" ồ..."
    textfix["\"Only the strongest spiders survive out here!\""] = "\"Chỉ có những con nhện mạnh nhất tồn tại ở đây!\""
    textfix["\"Only when all torches burn shall the way be revealed.\""] = "\"Chỉ khi mọi ngọn đuốc đều cháy sáng, lối đi mới được hé lộ.\""
    textfix["\"Ook OOK!\""] = "\"Hú HÚ! Khẹc KHẸC!\""
    textfix["\"Orphans cast upon the barren expanse. Lost in the wake of neglect.\""] = "\"Những đứa trẻ mồ côi bị bỏ rơi trên vùng đất cằn cỗi. Lạc lối vì bị bỏ rơi.\""
    textfix["\"PIRACY WARNING\""] = "\"CẢNH BÁO VI PHẠM VI PHẠM\""
    textfix["\"PRACTICE\"... HOW ORGANIC"] = "\"THỰC HÀNH\"... HỮU CƠ THẾ NÀO"
    textfix["\"PREPARING TO DIVE\""] = "\"CHUẨN BỊ ĐỂ KIẾM\""
    textfix["\"PROGRAMMED IN LAVASCRIPT\""] = "\"Được lập trình trong Lavascript\""
    textfix["\"Pardon me if I don't shake your hand.\""] = "\"Xin lỗi nếu tôi không bắt tay bạn.\""
    textfix["\"Paths are taken but once. Leap wisely, tarry not, or the abyss claims all.\""] = "\"Con đường chỉ được bước qua một lần. Hãy nhảy một cách khôn ngoan, đừng chần chừ, nếu không vực thẳm sẽ nuốt chửng tất cả.\""
    textfix["\"Perhaps I was wrong to dismiss the moon's power so quickly...\""] = "\"Có lẽ tôi đã sai khi loại bỏ sức mạnh của mặt trăng rất nhanh ...\""
    textfix["\"Perhaps I'll retire to a life of rose breeding.\""] = "\"Có lẽ tôi sẽ nghỉ hưu với cuộc sống chăn nuôi hoa hồng.\""
    textfix["\"Play with fire and you'll get burned.\""] = "\"Chơi với lửa và bạn sẽ bị đốt cháy.\""
    textfix["\"Please come home. I miss you so much.\""] = "\"Hãy về nhà. Tôi nhớ bạn rất nhiều.\""
    textfix["\"Plum\" is a 17th century term for \"fruit\", dear."] = "\"Mận\" là một thuật ngữ từ thế kỷ 17 để chỉ \"trái cây\", bạn thân mến."
    textfix["\"Potato purée\" is so much more fun to say than \"mashed potatoes\"."] = "\"Nghiền khoai tây\" nghe vui hơn \"khoai tây nghiền\" nhiều."
    textfix["\"Quiet your voice here. The trees slumber.\""] = "\"Hãy im lặng giọng nói của bạn ở đây. Những cái cây ngủ.\""
    textfix["\"Quoth the tallbird, Evermore.\""] = "\"Quoth the Tallbird, Evermore.\""
    textfix["\"RUSTED AND BUSTED\""] = "\"CHỈ VÀ XÓA\""
    textfix["\"Raaar! ...That's our bat noise.\""] = "\"Raaar! ... Đó là tiếng ồn dơi của chúng tôi.\""
    textfix["\"Raisins\""] = "\"Nho Khô\""
    textfix["\"Recipes are useful, but a true chef knows the importance of experimenting with new ingredients and flavors, and this world certainly provides an abundance of unusual things to choose from.\" -W"] = "\"Các công thức nấu ăn rất hữu ích, nhưng một đầu bếp thực thụ biết tầm quan trọng của việc thử nghiệm các nguyên liệu và hương vị mới, và thế giới này chắc chắn có vô số điều khác thường để bạn lựa chọn.\" -W"
    textfix["\"Rule one: don't set beehives on fire\"? This book's stupid!"] = "\"Quy tắc thứ nhất: không được đốt tổ ong\"? Cuốn sách này thật ngu ngốc!"
    textfix["\"Say, pal, I don't look so good.\""] = "\"Nói, bạn, tôi trông không tốt lắm.\""
    textfix["\"Science says I'll be nipping at your nose.\""] = "\"Khoa học nói rằng tôi sẽ ở mũi của bạn.\""
    textfix["\"Shadows are as black as ink, or night, or nightmares.\""] = "\"Bóng tối có màu đen như mực, hoặc đêm, hoặc những cơn ác mộng.\""
    textfix["\"Shadows are just inverted flames.\""] = "\"Bóng tối chỉ là ngọn lửa đảo ngược.\""
    textfix["\"Shhhh! No talking!\""] = "\"Xuỵtttt! Không nói chuyện!\""
    textfix["\"Sir Wolfgang is strongest boxer!\""] = "\"Ngài Wolfgang là võ sĩ mạnh nhất!\""
    textfix["\"Snowy peaks are a Canadian's natural habitat.\""] = "\"Những đỉnh núi tuyết là môi trường sống tự nhiên của Canada.\""
    textfix["\"So alluring...\""] = "\"Thật lôi cuốn...\""
    textfix["\"So few dare to delve into the secrets of dark magic.\""] = "\"Vì vậy, rất ít dám đào sâu vào bí mật của ma thuật tối.\""
    textfix["\"So many toys to build, and so little time!\""] = "\"Rất nhiều đồ chơi để xây dựng, và rất ít thời gian!\""
    textfix["\"So... does anyone work around here, or is it all festival all the time?\""] = "\"Vậy... có ai làm việc quanh đây không, hay lúc nào cũng là lễ hội?\""
    textfix["\"Someone\" had far too much time on his hands..."] = "Ai đó có quá nhiều thời gian rảnh..."
    textfix["\"Something is different... Wolfgang's head feels fuzzy...\""] = "\"Một cái gì đó khác biệt ... đầu của Wolfgang cảm thấy mờ nhạt ...\""
    textfix["\"Sometimes the old ways need to crash and burn to make way for the new.\""] = "\"Đôi khi những con đường cũ cần phải sụp đổ và cháy rụi để nhường chỗ cho những con đường mới.\""
    textfix["\"Sorry\"'s not gonna cut it this time!"] = "\"Xin lỗi\" lần này sẽ không hiệu quả đâu!"
    textfix["\"Stand back. I'm going to do SCIENCE!\""] = "\"Đứng lại. Tôi sẽ làm KHOA HỌC!\""
    textfix["\"Starlight is a blast from the past.\""] = "\"Starlight là một vụ nổ từ quá khứ.\""
    textfix["\"Surviving just requires strength of will. (And fire.)\""] = "\"Sống sót chỉ đòi hỏi sức mạnh của ý chí. (Và lửa.)\""
    textfix["\"Sweet slumber.\""] = "\"Ngủ ngọt.\""
    textfix["\"Swirly shiny!\""] = "\"Xu sáng bóng!\""
    textfix["\"THATAWAY\""] = "\"ĐÓ\""
    textfix["\"THE MOON AND I HAVE PLANS. GREAT PLANS\""] = "\"Mặt trăng và tôi có kế hoạch. Kế hoạch tuyệt vời\""
    textfix["\"THEY HAVE NOT INSTALLED A HEART\""] = "\"Họ chưa cài đặt trái tim\""
    textfix["\"THIS UNIT IS BATTLE READY\""] = "\"ĐƠN VỊ NÀY ĐANG BẮT ĐẦU\""
    textfix["\"That village was burnt before I got there.\""] = "\"Ngôi làng đó đã bị cháy trước khi tôi tới đó.\""
    textfix["\"That's a nice lookin' tree, eh? Not for long.\""] = "\"Đó là một cái nhìn đẹp, eh? Không lâu đâu.\""
    textfix["\"Thataway\"... Ugh!"] = "\"Rời đi\"... Ugh!"
    textfix["\"The Blacksmith's Soliloquy\""] = "\"Soliloquy của thợ rèn\""
    textfix["\"The Frogs Who Desired a King\"..."] = "\"Những chú ếch mong muốn có một vị vua\"..."
    textfix["\"The King's Soliloquy\""] = "\"Soliloquy của nhà vua\""
    textfix["\"The Merms are fiercely territorial, and quick to defend their homes. Though I honestly can't imagine anyone else wanting to take up residence in those ram-shackle hovels...\" -M"] = "\"Người Cá có tính lãnh thổ quyết liệt và nhanh chóng bảo vệ ngôi nhà của mình. Mặc dù thực lòng tôi không thể tưởng tượng được có ai khác muốn cư trú trong những túp lều lụp xụp đó...\" -M"
    textfix["\"The Pig men seem to harbor a deep dislike for the Constant's more monstrous denizens, attacking them on sight. While I personally can't blame them, it does pose a bit of a problem for some of my compatriots...\" -W"] = "\"Những người đàn ông Lợn dường như có ác cảm sâu sắc với những cư dân quái dị hơn của Constant, tấn công họ ngay trong tầm mắt. Mặc dù cá nhân tôi không thể đổ lỗi cho họ, nhưng điều đó gây ra một chút vấn đề cho một số đồng bào của tôi...\" -W"
    textfix["\"The Reunion\""] = "\"Cuộc hội ngộ\""
    textfix["\"The arm bone's connected to the...\" which bone was it..."] = "\"Xương cánh tay được kết nối với ...\" Cục nào nhẩy ..."
    textfix["\"The bushes I replanted by the camp are looking sickly... I suspect they'll require some extra care before they can produce any berries again.\" -W"] = "\"Những bụi cây tôi trồng lại gần trại trông ốm yếu... Tôi nghi ngờ chúng sẽ cần được chăm sóc thêm trước khi có thể ra quả trở lại.\" -W"
    textfix["\"The cosmos are filled with limitless scientific possibilities!\""] = "\"Các vũ trụ chứa đầy các khả năng khoa học vô hạn!\""
    textfix["\"The flames taught me how to dance.\""] = "\"Ngọn lửa dạy tôi cách nhảy.\""
    textfix["\"The hills will ring with Wolfgang's mighty yodels!\""] = "\"Những ngọn đồi sẽ vang lên với Yodels hùng mạnh của Wolfgang!\""
    textfix["\"The life of the party has arrived!\""] = "\"Cuộc sống của bữa tiệc đã đến!\""
    textfix["\"The moon in this world seems to hold some strange power over the creatures here. It changes them...\" -W"] = "\"Mặt trăng ở thế giới này dường như có sức mạnh kỳ lạ nào đó đối với các sinh vật ở đây. Nó thay đổi chúng...\" -W"
    textfix["\"The moon made us... different.\""] = "\"Mặt trăng làm cho chúng tôi ... khác biệt.\""
    textfix["\"The night is young, but not for long.\""] = "\"Đêm còn dài nhưng không dài đâu.\""
    textfix["\"The poor unsuspecting fool has no idea what's coming.\""] = "\"Kẻ ngu ngốc đáng thương không biết chuyện gì sắp xảy ra.\""
    textfix["\"The rain is proving to be a greater hindrance than I first anticipated. As if being soaked to the bone isn't dreadful enough, my tools keep slipping from my hands when I try to make use of them!\" -W"] = "\"Mưa đang trở thành một trở ngại lớn hơn tôi dự đoán ban đầu. Như thể việc ướt sũng đến tận xương vẫn chưa đủ khủng khiếp, các dụng cụ của tôi cứ tuột khỏi tay khi tôi cố gắng sử dụng chúng!\" -W"
    textfix["\"The root of all malady lies in an imbalance of the humors.\""] = "\"Căn nguyên của mọi bệnh tật nằm ở sự mất cân bằng của các chất dịch.\""
    textfix["\"The rose shelters our fur from the morning dew.\""] = "\"Những bông hoa hồng trú ẩn lông của chúng tôi từ sương buổi sáng.\""
    textfix["\"The sea shows no mercy to fools - and neither will I.\""] = "\"Biển không thương xót những kẻ ngốc - và tôi cũng vậy.\""
    textfix["\"The stage is set för my rise tö glöry!\""] = "\"Sân khấu đã được chuẩn bị cho sự vươn tới vinh quang của tôi!\""
    textfix["\"The thorned rose cannot help but prick. It is its nature.\""] = "\"Hoa hồng gai không thể không chích. Đó là bản chất của nó.\""
    textfix["\"The unknown hath been made known. The abyss revealed as refuge.\""] = "\"Điều chưa biết đã được biết đến. Vực thẳm được tiết lộ là nơi ẩn náu.\""
    textfix["\"The wheel on the gym goes round and round.\""] = "\"Bánh xe trong phòng tập thể dục quay tròn.\""
    textfix["\"There is a scientific solution, here. I know it.\""] = "\"Có một giải pháp khoa học, ở đây. Tôi biết điều đó.\""
    textfix["\"There is magic in the trees.\""] = "\"Có phép thuật trên cây.\""
    textfix["\"There is nothing but dark times ahead.\""] = "\"không có gì ngoài thời gian đen tối phía trước.\""
    textfix["\"There'll be no slip-ups while I'm in charge!\""] = "\"Sẽ không có sự trượt tuyết trong khi tôi chịu trách nhiệm!\""
    textfix["\"There's always more to do than there is time to do it.\""] = "\"Luôn có nhiều việc phải làm hơn là có thời gian để làm.\""
    textfix["\"There's few things more satisfying than watchin' something grow.\""] = "\"Có một vài điều thỏa mãn hơn so với xem một cái gì đó phát triển.\""
    textfix["\"These masked events are the playgrounds of merry mischief-makers!\""] = "\"Những sự kiện đeo mặt nạ này là sân chơi của những kẻ nghịch ngợm vui vẻ!\""
    textfix["\"These old threads I dug up aren't half bad, eh?\""] = "\"Những chủ đề cũ mà tôi đào lên không một nửa xấu, hả?\""
    textfix["\"They ain't beaver pelts, I'll tell ya that much.\""] = "\"Họ không phải là hải ly, tôi sẽ nói với bạn nhiều như vậy.\""
    textfix["\"They say the Shadow Queen herself comes at night to snatch up anyone foolish enough to wander in the dark...\" -W"] = "\"Người ta nói rằng Nữ hoàng Bóng tối đích thân đến vào ban đêm để tóm lấy bất cứ ai đủ ngu ngốc để đi lang thang trong bóng tối...\" -W"
    textfix["\"This Waymark is under development for a future update.\""] = "\"Waymark này đang được phát triển để cập nhật trong tương lai.\""
    textfix["\"This is where I keep my stuff.\""] = "\"Đây là nơi tôi giữ đồ đạc của mình.\""
    textfix["\"This lunar knowledge has been quite... eye-opening.\""] = "\"Kiến thức mặt trăng này đã khá ... mở mắt.\""
    textfix["\"This match will require a few more adjournments.\""] = "\"Trận đấu này sẽ yêu cầu thêm một vài lần hoãn lại.\""
    textfix["\"This may prove to be my most dangerous experiment yet.\""] = "\"Điều này có thể chứng minh là thí nghiệm nguy hiểm nhất của tôi.\""
    textfix["\"This vault shall become a tomb for all who dare trespass.\""] = "\"Hầm này sẽ trở thành lăng mộ cho bất kỳ kẻ nào dám xâm phạm.\""
    textfix["\"This world could not hold me.\""] = "\"Thế giới này không thể giữ tôi.\""
    textfix["\"This\" likely connects to a \"that.\""] = "“Cái này” có thể kết nối với “cái kia”."
    textfix["\"Thou art called by manifold names in myriad realms.\""] = "\"Ngươi được gọi bằng nhiều tên trong vô số cõi.\""
    textfix["\"Thought and conscientiousness nips all problems in the bud.\""] = "\"Suy nghĩ và lương tâm không có tất cả các vấn đề trong chồi.\""
    textfix["\"Through the Keystone, all kin and kind shall fall.\""] = "\"Thông qua Viên Đá Khóa, mọi thân tộc và đồng loại sẽ sụp đổ.\""
    textfix["\"Time seems to move slower in the depths of the forest.\""] = "\"Thời gian dường như trôi chậm hơn trong rừng sâu.\""
    textfix["\"Time to roll up my sleeves.\""] = "\"Thời gian để xắn tay áo lên.\""
    textfix["\"Time! I just need more time!\""] = "\"Thời gian! Tôi chỉ cần thêm thời gian!\""
    textfix["\"To change?\" No. It's a name..."] = "\"Thay đổi?\" Không. Đó là một cái tên..."
    textfix["\"To chop the tree, you must be the tree.\""] = "\"Để chặt cây, bạn phải là cây.\""
    textfix["\"To us, Thou art Shrouden. Many and one. Beyond all time. Beyond all realms.\""] = "\"Đối với chúng tôi, Ngài là Tấm vải liệm. Nhiều và một. Vượt trên mọi thời gian. Vượt trên mọi cõi.\""
    textfix["\"Today I was surprised to come upon a cobbled road - how did this hallmark of civilization come to be in this untamed wilderness?\" -W"] = "\"Hôm nay tôi rất ngạc nhiên khi bắt gặp một con đường rải sỏi - làm thế nào mà dấu ấn của nền văn minh này lại xuất hiện ở vùng hoang dã hoang sơ này?\" -W"
    textfix["\"Transdermal Induction Neurological Galvanic Learning Experience\" Uses electrolunetic technology to deliver shocks to conductive entities.\n\nOnce toggled, the T.I.N.G.L.E. node will search for another nearby node to link to, establishing an electric field between the two.\n\nNo physical harm is done (mental harm is up for debate). Most subjects will flee away after the brief shock.\n\nThe tester is recommended to use insulative gear to avoid this special learning experience!"] = "\"Trải nghiệm học tập điện thần kinh cảm ứng qua da\" Sử dụng công nghệ điện di để gây sốc cho các thực thể dẫn điện.\n\nSau khi được bật, T.I.N.G.L.E. nút sẽ tìm kiếm một nút khác gần đó để liên kết, thiết lập một điện trường giữa hai nút.\n\nKhông gây tổn hại về thể chất (có thể gây tổn hại về mặt tinh thần). Hầu hết các đối tượng sẽ bỏ chạy sau cú sốc ngắn.\n\nNgười thử nghiệm nên sử dụng thiết bị cách nhiệt để tránh trải nghiệm học tập đặc biệt này!"
    textfix["\"Trust none. The Shadow twists all it touches.\""] = "\"Đừng tin bất kỳ ai. Bóng Tối bóp méo mọi thứ nó chạm vào.\""
    textfix["\"Try not to cower in fear, my dear!\""] = "\"Cố gắng không thu mình lại vì sợ hãi, em yêu!\""
    textfix["\"Volcanic power is intoxicating.\""] = "\"Sức mạnh núi lửa là say sưa.\""
    textfix["\"WITH PARTS MADE IN JAPAN\""] = "\"Với các bộ phận được sản xuất tại Nhật Bản\""
    textfix["\"Want to hear a really scary story?\""] = "\"Bạn muốn nghe một câu chuyện thực sự đáng sợ?\""
    textfix["\"Watch for my extrusive igneous rocks, dear.\""] = "\"Hãy xem những tảng đá lửa đẫm máu của tôi, thân yêu.\""
    textfix["\"We all turn cold in time.\""] = "\"Tất cả chúng ta trở nên lạnh lùng theo thời gian.\""
    textfix["\"We are what we eat... sweet!\""] = "\"Chúng tôi là những gì chúng tôi ăn ... ngọt ngào!\""
    textfix["\"We don't want to fight if we don't have to.\""] = "\"Chúng tôi không muốn chiến đấu nếu chúng tôi không phải.\""
    textfix["\"We impish sorts do love our gold, hyuyu!\""] = "\"Chúng tôi các loại yêu thích vàng của chúng tôi, Hyuyu!\""
    textfix["\"We like parties!\""] = "\"Chúng tôi thích các bữa tiệc!\""
    textfix["\"We love playing in the snow!\""] = "\"Chúng tôi thích chơi trong tuyết!\""
    textfix["\"We nearly lost one of our number today. In a mad daze I created... something... that managed to pull our friend back to the land of the living, but... whatever it was, I fear I cannot rightfully say it was within the realm of science...\" -W"] = "\"Hôm nay chúng ta gần như mất đi một người. Trong cơn choáng váng điên cuồng, tôi đã tạo ra... thứ gì đó... có thể kéo bạn của chúng tôi trở lại vùng đất của người sống, nhưng... dù đó là gì đi nữa, tôi e rằng tôi không thể nói một cách đúng đắn rằng nó nằm trong lĩnh vực khoa học...\" -W"
    textfix["\"We remain faithful to Alter, as Alter remains faithful to us. Ever watching, knowing, waiting.\""] = "\"Chúng tôi vẫn trung thành với Alter, cũng như Alter vẫn trung thành với chúng tôi. Luôn theo dõi, biết, chờ đợi.\""
    textfix["\"We shouldn't hurt things that don't hurt us. If we're mean, bad old Mr. Krampus will come...\" -W"] = "\"Chúng ta không nên làm tổn thương những thứ không làm tổn thương chúng ta. Nếu chúng ta xấu tính, ông già Krampus xấu xa sẽ đến...\" -W"
    textfix["\"We were so lonely back then...\""] = "\"Lúc đó chúng tôi đã rất cô đơn ...\""
    textfix["\"We will celebrate as if we were in Valhalla!\""] = "\"Chúng tôi sẽ ăn mừng như thể chúng tôi ở Valhalla!\""
    textfix["\"We'll be on our best behavior... probably.\""] = "\"Chúng tôi sẽ cư xử tốt nhất... có lẽ vậy.\""
    textfix["\"We're always together, and never alone!\""] = "\"Chúng tôi luôn bên nhau, và không bao giờ cô đơn!\""
    textfix["\"We're going to play until the sun goes down, and then we're going to play some more.\""] = "\"Chúng ta sẽ chơi cho đến khi mặt trời lặn, rồi chúng ta sẽ chơi thêm nữa.\""
    textfix["\"We're like a walking volcano.\""] = "\"Chúng tôi giống như một ngọn núi lửa đi bộ.\""
    textfix["\"We're super excited to watch everyone open the presents we got them.\""] = "\"Chúng tôi vô cùng vui mừng khi thấy mọi người mở những món quà mà chúng tôi nhận được.\""
    textfix["\"Well, A Rather Beautifully Intelligent System.\" Uses a complicated assortment of cogs and circuitry for computing.\n\nOnce a target has been selected, as long as it stays in range, the W.A.R.B.I.S. begins calculating optimal performance to fight the target.\n\nThe armor improves the wearer's speed as it analyzes the target, ending at a 30% speed boost.\n\nWhen combined with the W.A.R.B.I.S. headgear, the two will sync up for a few moments sharing target information."] = "\"Chà, Một Hệ thống Thông minh Khá Đẹp.\" Sử dụng nhiều loại bánh răng và mạch điện phức tạp để tính toán.\n\nKhi mục tiêu đã được chọn, miễn là mục tiêu đó vẫn nằm trong phạm vi phủ sóng, W.A.R.B.I.S. bắt đầu tính toán hiệu suất tối ưu để chiến đấu với mục tiêu.\n\nBộ giáp cải thiện tốc độ của người mặc khi phân tích mục tiêu, kết thúc ở mức tăng tốc độ 30%.\n\nKhi kết hợp với W.A.R.B.I.S. mũ đội đầu, cả hai sẽ đồng bộ hóa trong giây lát để chia sẻ thông tin mục tiêu."
    textfix["\"Well, A Rather Beautifully Intelligent System.\" Uses a complicated assortment of cogs and circuitry for computing.\n\nOnce a target has been selected, as long as it stays in range, the W.A.R.B.I.S. begins calculating optimal performance to fight the target.\n\nThe head gear improves the wearer's damage as it analyzes the target, ending at a 20% damage increase.\n\nWhen combined with the W.A.R.B.I.S. armor, the two will sync up for a few moments sharing target information.\n\nWearing the W.A.R.B.I.S. Head Gear also provides the wearer with a Dramatically Updating Diagram (or D.U.D.) which provides information on which target is currently being analyzed and what level the W.A.R.B.I.S. has reached."] = "\"Chà, Một Hệ thống Thông minh Khá Đẹp.\" Sử dụng nhiều loại bánh răng và mạch điện phức tạp để tính toán.\n\nKhi mục tiêu đã được chọn, miễn là mục tiêu đó vẫn nằm trong phạm vi phủ sóng, W.A.R.B.I.S. bắt đầu tính toán hiệu suất tối ưu để chiến đấu với mục tiêu.\n\nThiết bị đeo đầu cải thiện sát thương của người đeo khi nó phân tích mục tiêu, kết thúc ở mức tăng 20% sát thương.\n\nKhi kết hợp với W.A.R.B.I.S. áo giáp, cả hai sẽ đồng bộ hóa trong giây lát để chia sẻ thông tin mục tiêu.\n\nĐeo W.A.R.B.I.S. Head Gear cũng cung cấp cho người đeo Sơ đồ cập nhật đáng kể (hoặc D.U.D.), cung cấp thông tin về mục tiêu nào hiện đang được phân tích và mức độ W.A.R.B.I.S. đã đạt tới."
    textfix["\"Well, at least Lucy thinks it's scary!\""] = "\"Chà, ít nhất Lucy nghĩ rằng nó đáng sợ!\""
    textfix["\"Well, what d'ya know? I scrub up mighty fine when I feel like it.\""] = "\"Ồ, bạn biết gì không? Tôi cọ rửa sạch sẽ khi tôi thấy thích.\""
    textfix["\"Whaddya say we get the gang together for some carols?\""] = "\"Có phải chúng ta sẽ tập hợp cả nhóm lại để hát một vài bài hát mừng không?\""
    textfix["\"What a treat it is to rub shoulders with the creme de la creme!\""] = "\"Thật là một điều trị để chà vai với creme de la creme!\""
    textfix["\"What strange new islands and creatures might I encounter if I journey out to sea? I shudder to think... but curiosity has a tendency to get the better of me...\" -W"] = "\"Tôi có thể gặp những hòn đảo và sinh vật mới lạ nào nếu ra khơi? Tôi rùng mình khi nghĩ... nhưng trí tò mò có xu hướng lấn át tôi...\" -W"
    textfix["\"What... happening...? Feel... strange...\""] = "\"Chuyện gì vậy ... xảy ra ...? Cảm thấy ... lạ ...\""
    textfix["\"Where are you Abigail? I thought I'd find you among the stars...\""] = "\"Abigail, em ở đâu? Tôi tưởng tôi sẽ tìm thấy em giữa các vì sao...\""
    textfix["\"Where should we go on our next adventure, Woby?\""] = "\"Chúng ta nên đi đâu trong chuyến phiêu lưu tiếp theo, Woby?\""
    textfix["\"Why couldn't it be warm fire?\""] = "\"Tại sao nó không thể là lửa ấm?\""
    textfix["\"Why did you leave me?\""] = "\"Tại sao mày bỏ rơi tao?\""
    textfix["\"Will you walk into my parlour?\""] = "\"Bạn sẽ bước vào phòng khách của tôi?\""
    textfix["\"Winter Feast is Wolfgang favorite time of year.\""] = "\"Lễ hội mùa đông là thời điểm Wolfgang yêu thích nhất trong năm.\""
    textfix["\"Woah, I'm smokin'! (No, really!)\""] = "\"Woah, tôi đang hút thuốc! (Không, thực sự!)\""
    textfix["\"Wolfgang is large moustache man! Ha ha!\""] = "\"Wolfgang là người đàn ông ria mép lớn! Ha ha!\""
    textfix["\"Wolfgang is learning much about history.\""] = "\"Wolfgang đang tìm hiểu nhiều về lịch sử.\""
    textfix["\"Wolfgang is mightiest pirate on the sea!\""] = "\"Wolfgang là cướp biển hùng mạnh nhất trên biển!\""
    textfix["\"Wolfgang is on the fire.\""] = "\"Wolfgang đang trên lửa.\""
    textfix["\"Wolfgang is strongest there ever was!\""] = "\"Wolfgang là mạnh nhất từng có!\""
    textfix["\"Wolfgang is tough. Lots of muscle.\""] = "\"Wolfgang là khó khăn. Rất nhiều cơ bắp.\""
    textfix["\"Wolfgang will carry moon to victory!\""] = "\"Wolfgang sẽ mang mặt trăng đến chiến thắng!\""
    textfix["\"Wolfgang will cook for you!\""] = "\"Wolfgang sẽ nấu ăn cho bạn!\""
    textfix["\"Won't you visit me at the heart of the labyrinth?\""] = "\"Bạn sẽ không đến thăm tôi ở trung tâm của mê cung?\""
    textfix["\"Would you like a sweetie, dear?\""] = "\"Bạn có muốn một người yêu, thân yêu?\""
    textfix["\"Wörds, wörds, wörds.\""] = "\"W  rds, w  rds, w  rds.\""
    textfix["\"X marks the spot\", eh?"] = "\"X đánh dấu vị trí\", hả?"
    textfix["\"YOU ARE HERE\""] = "\"BẠN ĐANG Ở ĐÂY\""
    textfix["\"Yacht not included.\""] = "\"Du thuyền không bao gồm.\""
    textfix["\"You are but a cog in my machine.\""] = "\"Bạn chỉ là một bánh răng trong máy của tôi.\""
    textfix["\"You are here\" it says, it says."] = "\"Bạn đang ở đây\" nó nói, nó nói."
    textfix["\"You are here\"... I wish I wasn't!"] = "\"Bạn đang ở đây\"... Tôi ước gì tôi không ở đây!"
    textfix["\"You are old, Father William,\" the young man said"] = "\"Bạn già, cha William,\" chàng trai trẻ nói"
    textfix["\"You can't run from Them forever. Take it from me, pal.\" -M"] = "\"Bạn không thể chạy khỏi họ mãi mãi. Lấy nó từ tôi, bạn.\" -M"
    textfix["\"You expect me to mingle? I was assured I'd have my own private box seat!\""] = "\"Bạn mong đợi tôi hòa nhập? Tôi đã yên tâm rằng mình sẽ có chỗ ngồi riêng trong hộp!\""
    textfix["\"You know what they say, you can't get charcoal without burning down a few trees!\" -W"] = "\"Bạn biết người ta nói gì không, bạn không thể kiếm được than nếu không đốt vài cái cây!\" -W"
    textfix["\"You scullion! You rampallian! You fustilarian! I'll tickle your catastrophe!\""] = "\"Đồ nhà bếp! Đồ hung hãn! Đồ tàn ác! Ta sẽ chọc tức thảm họa của ngươi!\""
    textfix["\"You seem to think you got a chance. Let's fix that.\""] = "\"Bạn dường như nghĩ rằng bạn có cơ hội. Hãy sửa chữa điều đó.\""
    textfix["\"You will kneel before might of Wolfgang!\""] = "\"Bạn sẽ quỳ gối trước khi có thể của Wolfgang!\""
    textfix["\"You, sir! How about a shave?\""] = "\"Bạn, thưa ngài! Làm thế nào về một cái cạo râu?\""
    textfix["\"Yöu have tö try harder than this tö defeat me!\""] = "\"Y  U có t   cố gắng hơn thế này đánh bại tôi!\""
    textfix["'Begs the question blue' colored dancing pants."] = "Quần khiêu vũ màu 'Đặt ra câu hỏi màu xanh'."
    textfix["'Cobaltous oxide blue' colored gloves suitable for all types of persons, robots, and monsters."] = "Găng tay màu 'xanh coban oxit' phù hợp với mọi loại người, robot và quái vật."
    textfix["'Crow blue' colored stripy trousers."] = "Quần sọc màu xanh quạ."
    textfix["'Cumulus gray' colored gloves suitable for all types of persons, robots, and monsters."] = "Găng tay màu 'Xám tích lũy' phù hợp với mọi loại người, robot và quái vật."
    textfix["'Disilluminated black' colored stripy trousers."] = "Quần sọc màu 'đen chói'."
    textfix["'Firehound red' colored gloves with a buckle on the back to help you hold it together."] = "Găng tay màu 'Firehound red' có khóa ở mặt sau để giúp bạn giữ chặt găng tay."
    textfix["'Flat fish tan' colored dancing pants."] = "Quần khiêu vũ màu 'phẳng cá'."
    textfix["'Forest guardian green' colored gloves suitable for all types of persons, robots, and monsters."] = "Găng tay màu 'Người bảo vệ rừng xanh' phù hợp với mọi loại người, robot và quái vật."
    textfix["'Higgsbury red' colored dancing pants."] = "Quần khiêu vũ màu 'đỏ Higgsbury'."
    textfix["'Houndbone white' colored shoes for picking winkles in."] = "Giày màu 'Houndbone trắng' để bắt mắt."
    textfix["'Ick' is right!"] = "Thật là kinh quá!"
    textfix["'Insufficient chocolate brown' colored stripy trousers."] = "Quần sọc màu 'không đủ màu nâu sô cô la'."
    textfix["'Jungle green' colored gloves with a buckle on the back to help you hold it together."] = "Găng tay màu 'rừng xanh' có khóa ở mặt sau để giúp bạn giữ chặt găng tay."
    textfix["'Leaves in autumn orange' colored gloves with a buckle on the back to help you hold it together."] = "Găng tay màu 'Lá mùa thu' có khóa sau lưng giúp bạn giữ chặt găng tay."
    textfix["'Lightning goat blue' colored socks for swimming in, if you could swim. Which you can't."] = "Tất màu 'xanh dê' để bơi lội, nếu bạn biết bơi. Mà bạn không thể."
    textfix["'Might take it to the kid."] = "'Có thể đưa nó cho đứa trẻ."
    textfix["'Pleasure."] = "'Vinh hạnh."
    textfix["'Plethora of purple' colored stripy trousers."] = "Quần sọc màu 'Plethora tím'."
    textfix["'Pure white' colored gloves suitable for all types of persons, robots, and monsters."] = "Găng tay màu 'trắng tinh khiết' phù hợp với mọi loại người, robot và quái vật."
    textfix["'Red gem red' colored gloves suitable for all types of persons, robots, and monsters."] = "Găng tay màu 'đỏ ngọc đỏ' phù hợp với mọi loại người, robot và quái vật."
    textfix["'Scribble black' colored gloves suitable for all types of persons, robots, and monsters."] = "Găng tay màu 'Scribble black' phù hợp với mọi loại người, robot và quái vật."
    textfix["'Sulfuric yellow' colored gloves suitable for all types of persons, robots, and monsters."] = "Găng tay màu 'vàng lưu huỳnh' phù hợp với mọi loại người, robot và quái vật."
    textfix["'Tis a Valkyrie."] = "'Đó là một Valkyrie."
    textfix["'Tis a ballad of good hap!"] = "'Đây là một bản ballad vui vẻ!"
    textfix["'Tis a deceitful mask."] = "Đây là một chiếc mặt nạ lừa dối."
    textfix["'Tis a fancy bowl."] = "Một chiếc bát trông rất sang trọng."
    textfix["'Tis a fancy plate."] = "'Đây là một chiếc đĩa ưa thích."
    textfix["'Tis a fencing spear."] = "'Đây là một ngọn giáo đấu kiếm."
    textfix["'Tis a fetor that doth offend thy very senses!"] = "'Đây là một fetor xúc phạm đến giác quan của bạn!"
    textfix["'Tis a fine fortress for a fish beast."] = "Một pháo đài kiên cố cho loài cá quái vật."
    textfix["'Tis a fine monument indeed."] = "Thực sự là một tượng đài tuyệt vời."
    textfix["'Tis a finely made shelter indeed!"] = "Đây quả thực là một nơi trú ẩn vững chắc!"
    textfix["'Tis a flavoring sprig."] = "'Đây là một nhánh hương liệu."
    textfix["'Tis a formidable task set before us,"] = "'Đây là một nhiệm vụ ghê gớm đặt ra trước mắt chúng ta,"
    textfix["'Tis a handful of seeds, for not-meat."] = "Đây là một nắm hạt, không phải thịt."
    textfix["'Tis a jaunty-hatted beast."] = "'Đây là một con thú có mũ vui nhộn."
    textfix["'Tis a magic light of short stature."] = "Một ngọn đèn phép thuật nhỏ bé."
    textfix["'Tis a map with no directions."] = "'Đây là một bản đồ không có hướng dẫn."
    textfix["'Tis a most sickly-smelling syrup."] = "Một lọ siro có mùi kinh khủng."
    textfix["'Tis a paltry bit of sea meat."] = "'Đây là một ít thịt biển."
    textfix["'Tis a pillow from Njoror's domain."] = "'Đây là một chiếc gối từ lãnh địa của Njoror."
    textfix["'Tis a piteous ship, but I shall make do."] = "'Đó là một con tàu đáng thương, nhưng tôi sẽ làm được."
    textfix["'Tis a place for workers, not warriors."] = "Đây là nơi dành cho người lao động, không phải chiến binh."
    textfix["'Tis a post. Unworthy of mine attention."] = "Chỉ là một cột trụ. Không đáng để ta để ý."
    textfix["'Tis a powerful elixir!"] = "Một lọ tiên dược mạnh mẽ!"
    textfix["'Tis a runestone."] = "'Đây là một runestone."
    textfix["'Tis a sad day for the fish beasts."] = "Một ngày buồn cho loài cá quái vật."
    textfix["'Tis a spider war horn."] = "Đây là một chiếc tù và chiến tranh của loài nhện."
    textfix["'Tis a task for one."] = "'Đây là một nhiệm vụ cho một người."
    textfix["'Tis a trap!"] = "Đây là một cái bẫy!"
    textfix["'Tis a tree pelt."] = "'Đây là một tấm da cây."
    textfix["'Tis a tribute worthy of the Pig Gods."] = "Một sự cống nạp xứng đáng cho các thần Heo."
    textfix["'Tis a weapon of beastly slaughter!"] = "'Đây là vũ khí tàn sát dã thú!"
    textfix["'Tis a wicked looking thing."] = "Trông thật tà ác."
    textfix["'Tis all that remains."] = "Đây là tất cả những gì còn sót lại."
    textfix["'Tis an abomination!"] = "Thật là một sự ghê tởm!"
    textfix["'Tis an instrument to vanquish food."] = "'Đây là một công cụ để tiêu diệt thức ăn."
    textfix["'Tis an iron golem."] = "'Đây là một con golem sắt."
    textfix["'Tis as dry as an empty well!"] = "'Nó khô như cái giếng rỗng!"
    textfix["'Tis barren."] = "Cây này đã cằn cỗi."
    textfix["'Tis battered, but not lost!"] = "'Tis bị đánh đập, nhưng không bị mất!"
    textfix["'Tis better to wear than eat them, I suppose."] = "'Tôi cho rằng mặc thì tốt hơn là ăn chúng."
    textfix["'Tis broken."] = "'Nó hỏng rồi."
    textfix["'Tis but a fragment of a complete pattern."] = "Đây chỉ là một mảnh của một khuôn mẫu hoàn chỉnh."
    textfix["'Tis but a jumbled mess of words."] = "'Đây chỉ là một mớ hỗn độn của các từ."
    textfix["'Tis but another fallen fish beast."] = "Đây là một con cá sa ngã khác."
    textfix["'Tis cowardly to hide one's face behind a mask!"] = "Thật hèn nhát khi che giấu khuôn mặt sau chiếc mặt nạ!"
    textfix["'Tis cursed!"] = "'Thật là đáng nguyền rủa!"
    textfix["'Tis dead but its parts may bring new life to another."] = "'Nó đã chết nhưng các bộ phận của nó có thể mang lại sự sống mới cho một loài khác."
    textfix["'Tis dead."] = "Chết rồi."
    textfix["'Tis dedicated to its god."] = "Được dựng nên để tôn thờ vị thần của chúng."
    textfix["'Tis dry. I shall see to it later."] = "'Khô rồi. Tôi sẽ xem xét nó sau."
    textfix["'Tis empty."] = "'Nó trống rỗng."
    textfix["'Tis enough to gorge themselves to the gills!"] = "Đủ để chúng no căng mang rồi!"
    textfix["'Tis excess!"] = "'Thật quá đáng!"
    textfix["'Tis filled with too many non-meat dishes if you ask me."] = "'Có quá nhiều món không phải thịt nếu bạn hỏi tôi."
    textfix["'Tis fit only for the beasts."] = "'Nó chỉ phù hợp với những con thú."
    textfix["'Tis food for birds, not Vikings."] = "'Đây là thức ăn cho chim, không phải cho người Viking."
    textfix["'Tis for the fish beasts."] = "Đây là dành cho lũ quái vật cá."
    textfix["'Tis friend, no longer foe."] = "'Đây là bạn, không còn là kẻ thù."
    textfix["'Tis full of goods."] = "'Có đầy đủ hàng hóa."
    textfix["'Tis futile to roll it further."] = "'Thật vô ích khi cuộn nó thêm nữa."
    textfix["'Tis hardly a sword at all."] = "'Nó hầu như không phải là một thanh kiếm."
    textfix["'Tis imbued with the power of the moon!"] = "Nó được thấm đẫm sức mạnh của mặt trăng!"
    textfix["'Tis in use, and not by me."] = "'Nó được sử dụng chứ không phải bởi tôi."
    textfix["'Tis little more than set-dressing."] = "'Nó chỉ hơn việc mặc quần áo một chút thôi."
    textfix["'Tis marring mine musings."] = "'Đây là sự suy ngẫm của tôi."
    textfix["'Tis merely biding its time."] = "Nó chỉ đang chờ thời cơ mà thôi."
    textfix["'Tis naught but a pest to be crushed beneath my boot!"] = "'Không có gì khác hơn là một loài gây hại bị nghiền nát dưới ủng của tôi!"
    textfix["'Tis naught but food for worms."] = "'Không có gì ngoài thức ăn cho giun."
    textfix["'Tis no Bifrost, but 'twill do."] = "Không phải là Bifrost, nhưng vậy cũng tạm ổn."
    textfix["'Tis no time for pleasantries!"] = "'Không có thời gian để đùa giỡn đâu!"
    textfix["'Tis no use to me in this form."] = "'Tôi không có ích gì trong hình thức này."
    textfix["'Tis not a door for a warrior of my size."] = "'Đây không phải là cánh cửa dành cho một chiến binh tầm cỡ như tôi."
    textfix["'Tis not a treasure worth taking."] = "'Đây không phải là một kho báu đáng để lấy đi."
    textfix["'Tis not battle ready yet."] = "'Trận chiến vẫn chưa sẵn sàng."
    textfix["'Tis not for me."] = "'Nó không dành cho tôi."
    textfix["'Tis not just strength, but cunning that makes a warrior!"] = "'Không chỉ sức mạnh mà sự khôn ngoan mới tạo nên một chiến binh!"
    textfix["'Tis not mine.'"] = "'Nó không phải của tôi.'"
    textfix["'Tis not my time to fall!"] = "'Đây không phải là lúc tôi gục ngã!"
    textfix["'Tis not to its liking."] = "'Nó không theo ý thích của nó."
    textfix["'Tis not unlike the garb of a forest nymph."] = "'Nó không khác gì trang phục của một nữ thần rừng."
    textfix["'Tis rather useful for a foul little doll."] = "Khá hữu dụng cho một con búp bê xấu xí."
    textfix["'Tis ready to be pillaged!"] = "'Tis đã sẵn sàng để bị cướp bóc!"
    textfix["'Tis sadly not a weapon, but I enjoy it nonetheless."] = "'Đáng buồn là nó không phải là vũ khí, nhưng dù sao thì tôi cũng thích nó."
    textfix["'Tis said this humble seed holds mighty potential."] = "'Tis nói rằng hạt giống khiêm tốn này có tiềm năng to lớn."
    textfix["'Tis shielded!"] = "Nó đã được bảo vệ!"
    textfix["'Tis small, but lively!"] = "'Nó nhỏ nhưng sống động!"
    textfix["'Tis spirited."] = "Thật là hăng hái."
    textfix["'Tis surrounded by a thorny thicket."] = "Nó được bao quanh bởi những bụi gai dày đặc."
    textfix["'Tis tall enough!'"] = "'Đủ cao rồi!'"
    textfix["'Tis the key to another world."] = "'Đây là chìa khóa dẫn tới một thế giới khác."
    textfix["'Tis the lights of Valhalla?"] = "Đó có phải là ánh sáng của Valhalla?"
    textfix["'Tis the machine from my vision."] = "'Đây là cỗ máy trong tầm nhìn của tôi."
    textfix["'Tis the mark of a noble leader to care for her warriors so."] = "Đây là dấu hiệu của một lãnh đạo cao quý, chăm sóc chiến binh của mình."
    textfix["'Tis the prettiest little parlour that ever you did spy."] = "'Đây là phòng khách nhỏ đẹp nhất mà bạn từng do thám."
    textfix["'Tis the way of things."] = "Đó là quy luật của tự nhiên."
    textfix["'Tis too bright for sleep!"] = "'Trời sáng quá không ngủ được!"
    textfix["'Tis too far from the festivities!"] = "'Quá xa lễ hội!"
    textfix["'Tis too late for revelry!"] = "'Đã quá muộn để vui chơi!"
    textfix["'Tis vanquished."] = "'Nó đã bị đánh bại."
    textfix["'Tis what the Gnaw desires, paltry though it is."] = "Đây là thứ mà Gnaw khao khát, dù trông thật nhỏ bé."
    textfix["'Tis wood, forged in the sea's depths!"] = "'Đây là gỗ, được rèn dưới đáy biển sâu!"
    textfix["'Twas a battle to sing of."] = "'Đó là một trận chiến để hát."
    textfix["'Twas a fiery display indeed!"] = "Thật là một cảnh tượng rực lửa!"
    textfix["'Twas a hard-fought battle, but we prevailed!"] = "'Đó là một trận chiến khó khăn, nhưng chúng tôi đã thắng!"
    textfix["'Twas a poison, most assuredly."] = "Chắc chắn đó là một loại độc dược."
    textfix["'Twas a spiky foe."] = "'Đó là một kẻ thù gai góc."
    textfix["'Twas all in vain!"] = "'Tất cả đều vô ích!"
    textfix["'Twas an honor to fight thee."] = "'Thật vinh dự khi được chiến đấu với ngươi."
    textfix["'Twas an unnatural thing. Slaying it was a kindness."] = "'Đó là một điều không tự nhiên. Giết nó là một lòng tốt."
    textfix["'Twas but a snack."] = "'Chỉ là một bữa ăn nhẹ thôi."
    textfix["'Twas consumed by Hel's fire."] = "'Twas bị ngọn lửa của Hel thiêu rụi."
    textfix["'Twas consumed by a mighty inferno!"] = "'Twas bị tiêu diệt bởi một địa ngục hùng mạnh!"
    textfix["'Twas consumed by flames."] = "'Twas bị ngọn lửa thiêu rụi."
    textfix["'Twas devoured by Hel's fire!"] = "Đã bị thiêu rụi bởi ngọn lửa của Hel!"
    textfix["'Twas forged in flame."] = "Được rèn nên từ lửa."
    textfix["'Twas left by cities past."] = "'Twas do các thành phố trong quá khứ để lại."
    textfix["'Twas made in honor of our stalwart vessel!"] = "'Nó được làm để vinh danh con tàu vững chắc của chúng ta!"
    textfix["'Twas my pleasure dispatching that beast."] = "'Tôi rất hân hạnh được phái con thú đó đi."
    textfix["'Twas no match for my spear."] = "'Nó không thể sánh được với ngọn giáo của tôi."
    textfix["'Twas no match for this great heat."] = "Nó chẳng thể chống chọi lại cơn nóng dữ dội này."
    textfix["'Twas not made for a warrior."] = "Thứ này không dành cho chiến binh."
    textfix["'Twas not meant for mortal eyes."] = "'Nó không dành cho đôi mắt phàm trần."
    textfix["'Twas not one of my more graceful exits..."] = "'Đó không phải là một trong những lối thoát duyên dáng hơn của tôi..."
    textfix["'Twas of little use anyway."] = "‘Dù sao thì cũng chẳng ích gì mấy."
    textfix["'Twas pillaged long ago."] = "'Đã bị cướp bóc từ lâu rồi."
    textfix["'Twas plucked straight from my nightmares!"] = "'Twas đã thoát ra khỏi cơn ác mộng của tôi!"
    textfix["'Twas the last stone, cut and set."] = "'Đó là viên đá cuối cùng, được cắt và đặt."
    textfix["'Twas the site of a vicious raid."] = "'Đó là địa điểm của một cuộc đột kích tàn khốc."
    textfix["'Twas won in an invigorating battle!"] = "Chiến lợi phẩm từ một trận chiến đầy phấn khích!"
