    textfix["... Yes, hail Metheus."] = "... Vâng, chào mừng Metheus."
    textfix["... my brood."] = "... bố mẹ của tôi."
    textfix["...(crunch)..."] = "...(khủng hoảng)..."
    textfix["...(growl)..."] = "...(gầm gừ)..."
    textfix["....Thank you, flort."] = "....Cám ơn, Phờ lọt."
    textfix["...And now it's on fire."] = "...Và bây giờ nó đang cháy."
    textfix["...BECOME THE BEE..."] = "...Trở thành con ong..."
    textfix["...But don't worry, the hook man can't get you out here!"] = "...Nhưng đừng lo lắng, hắn sẽ không đến với bạn được đâu!"
    textfix["...But we will live to fight again!!"] = "... Nhưng chúng ta sẽ sống để chiến đấu một lần nữa !!"
    textfix["...But why does it have a mouse head?"] = "...Nhưng tại sao nó lại có đầu chuột?"
    textfix["...Demolition's rescheduled."] = "...Việc phá hủy được lên lịch lại."
    textfix["...Do you understand the forces you serve?"] = "... Bạn hiểu, bạn phục vụ ai?"
    textfix["...Don't like stories in that book."] = "...Không thích những câu chuyện trong cuốn sách đó."
    textfix["...Ew."] = "... Ew."
    textfix["...Gaaah!"] = "...Gaaa!"
    textfix["...Guess you pretty okay, florpt."] = "...Có lẽ cậu khá ổn đấy, phọpt."
    textfix["...Has anyone checked in on him recently?"] = "...Gần đây có ai kiểm tra anh ấy không?"
    textfix["...I can't be disappointed... If I expect nothing..."] = "...Tôi không thể thất vọng... Nếu tôi không mong đợi gì..."
    textfix["...I should try to stay on her good side."] = "...Tôi nên cố gắng đứng về phía cô ấy."
    textfix["...I suppose that is an improvement."] = "... Tôi cho rằng đó là một cải tiến."
    textfix["...I think I understand now."] = "... Tôi nghĩ bây giờ tôi đã hiểu."
    textfix["...I wonder how my brother is doing."] = "...Tôi không biết anh trai tôi thế nào rồi."
    textfix["...Maxwell left his stuff out again."] = "... Maxwell lại bỏ đồ của mình ra."
    textfix["...Maybe someone else will take it."] = "...Có lẽ ai đó sẽ lấy nó."
