    textfix["California Roll"] = "Cơm Cuộn California"
    textfix["Call Cataclysm"] = "Gọi Đại Họa"
    textfix["Call Woby"] = "Gọi Woby"
    textfix["Call down lightning from dark, brooding storm clouds."] = "Gọi xuống Lightning từ bóng tối, nghiền nát những đám mây bão."
    textfix["Call forth the beasts!"] = "Gọi ra những con quái vật!"
    textfix["Call me \"Mr. Sandman\"."] = "Hãy gọi tôi là \"Ông Sandman\"."
    textfix["Call me Sisyphus."] = "Gọi tôi là Sisyphus."
    textfix["Call on the power of otherworldly stars."] = "Kêu gọi sức mạnh của các ngôi sao thế giới khác."
    textfix["Call on the rabbits to keep your stuff, anytime, any hare."] = "Gọi những chú thỏ để giữ đồ của bạn, bất cứ lúc nào, bất cứ nơi nào."
    textfix["Call thy hordes, they shan't protect thee!"] = "Hãy gọi đám đông của bạn đi, họ sẽ không bảo vệ bạn đâu!"
    textfix["Call upon the power of darkness."] = "Kêu gọi sức mạnh bóng đêm."
    textfix["Call upon the power of the trees."] = "Kêu gọi sức mạnh của cây."
    textfix["Call your creepy crawly friends."] = "Gọi lũ bạn bò lổm ngổm rùng rợn của bạn."
    textfix["Call'th to memory the lays of the Havfrue."] = "Hãy nhớ lại sự ra đời của Havfrue."
    textfix["Called it."] = "Đã gọi nó."
    textfix["Calling big Pull Rock here"] = "Kêu gọi Pull Rock lớn tới đây"
    textfix["Calling it a \"castle\" is plainly incorrect."] = "Gọi nó là “lâu đài” là không chính xác."
    textfix["Calling it a \"wall\" is kind of a stretch."] = "Gọi nó là “bức tường” thì hơi quá."
    textfix["Calling it a bush is quite charitable."] = "Gọi nó là bụi cây thật là một sự rộng lượng."
    textfix["Calling that \"light\" wouldn't be quite right."] = "Gọi đó là “ánh sáng” thì không đúng lắm."
    textfix["Calls forth a Portable Den."] = "Triệu hồi một Hang ổ di động."
    textfix["Calls little Fire Friends"] = "Gọi những người bạn lửa nhỏ"
    textfix["Calm"] = "Xoa dịu"
    textfix["Calm Palm Shirt"] = "Áo Cọ Bình Tĩnh"
    textfix["Caloric, but nutritious. It smells wonderful, as well."] = "Nhiều calo, nhưng bổ dưỡng. Nó cũng có mùi thơm tuyệt vời."
    textfix["Came from Tweeter"] = "Đến từ Tweeter"
    textfix["Came from far away"] = "Đến từ nơi rất xa"
    textfix["Camellia Flowerbed"] = "Thảm hoa trà"
    textfix["Camellia Flowerbed Portrait"] = "Chân dung hoa Camellia"
    textfix["Camera Control"] = "Điều khiển máy ảnh"
    textfix["Camera Rotation:"] = "Xoay Camera"
    textfix["Camera and Inventory"] = "Máy ảnh và hàng tồn kho"
    textfix["Camouflage!"] = "Ngụy trang!"
    textfix["Camouflage."] = "Ngụy trang."
    textfix["Camper's Tent"] = "Lều Trại"
    textfix["Campfire"] = "Lửa trại"
    textfix["Campfire Camera:"] = "Camera lửa trại:"
    textfix["Campfire Enthusiast"] = "Người đam mê lửa trại"
    textfix["Campfire Story"] = "Câu chuyện lửa trại"
    textfix["Campfire stories are best enjoyed with a group of friends on eerie, moonlit nights."] = "Những câu chuyện về lửa trại sẽ thú vị nhất khi được thưởng thức cùng một nhóm bạn vào những đêm trăng kỳ lạ."
    textfix["Campfire!"] = "Lửa trại!"
    textfix["Can I add it to my helmet?"] = "Tôi có thể thêm nó vào mũ bảo hiểm của tôi không?"
    textfix["Can I blow this down?"] = "Tôi có thể thổi bay cái này được không?"
    textfix["Can I burn it now?"] = "Tôi có thể đốt nó bây giờ được không?"
    textfix["Can I call it seafood? It's more of a pondfood, really."] = "Tôi có thể gọi nó là hải sản không? Thật ra nó giống thức ăn ao hồ hơn."
    textfix["Can I cook marshmallows over it though?"] = "Tôi có thể nấu kẹo dẻo qua nó không?"
    textfix["Can I eat something that's not slimy for once?"] = "Tôi có thể ăn thứ gì đó không nhầy nhụa một lần được không?"
    textfix["Can I eat those?"] = "Tôi có thể ăn những thứ đó không?"
    textfix["Can I get a bigger bowl? This one looks a little shrimpy."] = "Tôi có thể được một cái bát lớn hơn không? Cái này trông nhỏ bé quá."
    textfix["Can I go back to a time before I ate that?"] = "Tôi có thể quay lại một thời gian trước khi tôi ăn không?"
    textfix["Can I invoke the \"no holiday decorations\" Klaus?"] = "Tôi có thể triệu hồi Klaus \"không trang trí lễ hội\" không?"
    textfix["Can I just get a taste?"] = "Tôi có thể nếm thử được không?"
    textfix["Can I just wait here for everyone to be done?"] = "Liệu tôi có thể chỉ đợi ở đây cho mọi người hoàn thành cuộc đua của mình?"
    textfix["Can I keep them? Pleeeaaaase?"] = "Tôi có thể giữ chúng được hônggggg? Xin moàaaa?"
    textfix["Can I make the next one?"] = "Tôi có thể làm cái tiếp theo không?"
    textfix["Can I make this into cheese?"] = "Tôi có thể làm món này thành pho mát được không?"
    textfix["Can I play too? Uh... I mean, use my Pioneer tracking expertise?"] = "Tôi cũng có thể chơi được không? Uh ... Ý tôi là, sử dụng chuyên môn theo dõi đầy tính tiên phong của tôi?"
    textfix["Can I really even call it a \"box\"?"] = "Tôi thực sự có thể gọi nó là \"chiếc hộp\" không?"
    textfix["Can I set it on fire?"] = "Tôi có thể đốt nó được không?"
    textfix["Can I use that after you?"] = "Tôi có thể sử dụng nó sau bạn được không?"
    textfix["Can I... help set up the carnival?"] = "Tôi có thể... giúp tổ chức lễ hội được không?"
    textfix["Can I... play next?"] = "Tôi có thể... chơi tiếp được không?"
    textfix["Can Row in water to move a boat in a desired direction."] = "Có thể chèo trong nước để di chuyển một chiếc thuyền theo hướng mong muốn."
    textfix["Can Wolfgang help make scribblemarks when you're done?"] = "Wolfgang có thể giúp bạn viết nguệch ngoạc khi bạn làm xong không?"
    textfix["Can a machine truly die?"] = "Một cỗ máy có thể thực sự chết?"
    textfix["Can a merm and a pig put their differences aside to save themselves?"] = "Liệu người cá và lợn có thể bỏ qua sự khác biệt để tự cứu mình không?"
    textfix["Can a rock possess a soul?"] = "Một tảng đá có thể có linh hồn không?"
    textfix["Can always count on me!"] = "Luôn có thể tin tưởng vào tôi!"
    textfix["Can be Played to cause small geysers to shoot up from the ocean, doing damage to creatures and structures."] = "Có thể được chơi để khiến các mạch nước nhỏ bắn lên từ đại dương, gây thiệt hại cho các sinh vật và cấu trúc."
    textfix["Can be added to Crock Pot food using a Portable Seasoning Station.\n\nEating a dish spiced with Chili Flakes adds 20% damage to their attacks.\n\nDuration 4 minutes.\n\nAlso raises temperature 15 degrees for 15 seconds."] = "Có thể thêm vào thức ăn trong Nồi Hầm bằng cách sử dụng Trạm Gia vị Di động.\n\nĂn một món ăn có tẩm Ớt sẽ tăng thêm 20% sát thương cho các đòn tấn công của chúng.\n\nThời gian kéo dài 4 phút.\n\nĐồng thời tăng nhiệt độ lên 15 độ trong 15 giây."
    textfix["Can be added to Crock Pot food using a Portable Seasoning Station.\n\nEating a dish spiced with Garlic reduces the damage they take to their health by 33%.\n\nDuration 4 minutes."] = "Có thể thêm vào thức ăn trong Nồi Hầm bằng cách sử dụng Trạm Gia vị Di động.\n\nĂn một món ăn có gia vị Tỏi giúp giảm 33% tổn thương gây ra cho sức khỏe.\n\nThời lượng 4 phút."
    textfix["Can be added to Crock Pot food using a Portable Seasoning Station.\n\nEating a dish spiced with Honey Crystals doubles their rate of Mining Chopping and Hammering.\n\nDuration 4 minutes."] = "Có thể thêm vào thức ăn trong Nồi Hầm bằng cách sử dụng Trạm Gia vị Di động.\n\nĂn một món ăn được tẩm Tinh thể Mật ong sẽ tăng gấp đôi tốc độ Khai thác Chặt và Búa.\n\nThời lượng 4 phút."
    textfix["Can be added to Crock Pot food using a Portable Seasoning Station.\n\nEating a dish spiced with Seasoning Salt grants 25% more healing for healing effects.\n\nDuration 4 minutes."] = "Có thể thêm vào thức ăn trong Nồi Hầm bằng cách sử dụng Trạm Gia vị Di động.\n\nĂn một món ăn được tẩm Muối Gia vị giúp tăng thêm 25% hiệu quả hồi máu.\n\nThời lượng 4 phút."
    textfix["Can be hung in special trees grown in a Festive Tree Planter."] = "Có thể treo trên các cây đặc biệt được trồng trong Festive Tree Planter."
    textfix["Can be loaded with cannoballs.\n\nOnce loaded, it can be aimed to fire. The direction can be changed by standing next to it from different sides before aiming."] = "Có thể nạp đạn súng thần công.\n\nSau khi nạp, nó có thể nhắm bắn. Hướng có thể được thay đổi bằng cách đứng cạnh nó từ các phía khác nhau trước khi nhắm."
    textfix["Can be mined down to reveal a darker core made of harder material."] = "Có thể được khai thác xuống để tiết lộ một lõi tối hơn làm bằng vật liệu cứng hơn."
    textfix["Can be mined for Shell Bells."] = "Có thể được khai thác cho chuông vỏ."
    textfix["Can be placed on dirt ground to change the type of ground."] = "Có thể được đặt trên mặt đất bụi bẩn để thay đổi loại mặt đất."
    textfix["Can be planted in the ground."] = "Có thể được trồng trong lòng đất."
    textfix["Can be planted on Sea Stacks."] = "Có thể được trồng trên ngăn xếp biển."
    textfix["Can be planted on the ground."] = "Có thể được trồng trên mặt đất."
    textfix["Can be put on Totally Normal Trees as decoration."] = "Có thể được đặt trên cây hoàn toàn bình thường như trang trí."
    textfix["Can be put onto a Beefalo if it's willing."] = "Có thể được đặt lên một con bò nếu nó sẵn sàng."
    textfix["Can be put onto a Beefalo if it's willing. Faster than a regular saddle."] = "Có thể gắn lên một con Beefalo nếu nó muốn. Nhanh hơn yên thông thường."
    textfix["Can be put onto a Beefalo if it's willing. Increases speed over a regular saddle."] = "Có thể được đặt lên một con bò nếu nó sẵn sàng. Tăng tốc độ trên một yên xe thông thường."
    textfix["Can be put onto a Beefalo if it's willing. Slower than a regular saddle."] = "Có thể gắn vào Beefalo nếu nó muốn. Chậm hơn yên thông thường."
    textfix["Can be repaired by feeding it food."] = "Có thể được sửa chữa bằng cách cho ăn thức ăn."
    textfix["Can be repaired using the inventory wall items.\n\nCan be build up 4 levels."] = "Có thể sửa chữa bằng cách sử dụng các vật phẩm trên tường trong kho.\n\nCó thể xây dựng 4 cấp độ."
    textfix["Can be thrown into the sea to create a pair of connected Whirlportals. Boats sailing close to them will be brought to the other entrance."] = "Có thể được ném xuống biển để tạo ra một Xoáy Nước được kết nối. Thuyền đi thuyền gần họ sẽ được đưa đến lối vào khác."
    textfix["Can be turned on and off. While fueled and on, if a fire appears within its range, it will fling a snowball at it to put it out."] = "Có thể được bật và tắt. Trong khi được thúc đẩy và bật, nếu một đám cháy xuất hiện trong phạm vi của nó, nó sẽ ném một quả cầu tuyết vào đó để đưa nó ra."
    textfix["Can be unwrapped to release items inside."] = "Có thể được mở ra để phát hành các mục bên trong."
    textfix["Can be used on Beefalo to collect Beefalo Wool.\n\nIncreases Beefalo Obedience 40% and increases Beefalo domestication by 1.6% once per day."] = "Có thể sử dụng trên Bò Lai để thu thập Lông Bò Lai.\n\nTăng Sự Vâng Phục của Bò Lai 40% và tăng khả năng thuần hóa Bò Lai thêm 1,6% một lần mỗi ngày."
    textfix["Can be used to block attacks. Successfully blocking an attack decreases the block cooldown.\n\nIt can only be equipped by Wigfrids who have the \"Battle Rönd\" skill."] = "Có thể được sử dụng để chặn các cuộc tấn công. Chặn thành công một đòn tấn công sẽ giảm thời gian hồi chiêu của khối.\n\nNó chỉ có thể được trang bị bởi Wigfrids có kỹ năng \"Khiên Chiến\"."
    textfix["Can be used to carve specific shapes on Giant Pumpkins."] = "Có thể dùng để khắc các hình dạng cụ thể trên Bí ngô Khổng lồ."
    textfix["Can be used to heal 8 health."] = "Có thể được sử dụng để chữa lành sức khỏe 8."
    textfix["Can bring back Wolfgang hair-cow?"] = "Có thể mang về tóc bò của Wolfgang?"
    textfix["Can build Floaty stuff"] = "Có thể xây dựng công cụ Floaty"
    textfix["Can build with power of moon!"] = "Có thể xây dựng với sức mạnh của mặt trăng!"
    textfix["Can buy things now!"] = "Có thể mua đồ ngay bây giờ!"
    textfix["Can crabby lady live in swamp!? Florp!"] = "Cô nàng cáu kỉnh có thể sống ở đầm lầy được không!? Florp!"
    textfix["Can create light. Willow, Walter and Warly can use it to cook food.\n\nWill lose durability faster in the rain."] = "Có thể tạo ra ánh sáng. Willow, Walter và Warly có thể dùng nó để nấu thức ăn.\n\nSẽ mất độ bền nhanh hơn khi trời mưa."
    textfix["Can do it too! Mermfolk super strong, flurt!"] = "Cũng có thể làm được! Người cá siêu mạnh, bay đi!"
    textfix["Can eat it? No? Aww..."] = "Có thể ăn nó? KHÔNG? Ôi..."
    textfix["Can eat now? Maybe now? Now?"] = "Bây giờ có thể ăn được không? Có lẽ bây giờ? Hiện nay?"
    textfix["Can eat yours if you don't want them, florp."] = "Có thể ăn của anh nếu anh không muốn, phọp."
    textfix["Can fix it?"] = "Có thể sửa nó?"
    textfix["Can fix or take parts! Me choose."] = "Có thể sửa hoặc lấy linh kiện! Tôi chọn."
    textfix["Can fix people!"] = "Có thể sửa chữa mọi người!"
    textfix["Can fly with it? No"] = "Có thể bay với nó? KHÔNG"
    textfix["Can go now"] = "Có thể đi bây giờ"
    textfix["Can go zoomy now!"] = "Có thể phóng to ngay bây giờ!"
    textfix["Can have some? Pleeaaase?"] = "Có thể có một số? Xin vui lòng?"
    textfix["Can he make one for Abigail?"] = "Anh ấy có thể làm một cái cho Abigail không?"
    textfix["Can help decorate too, florp!"] = "Có thể giúp trang trí nữa, florp!"
    textfix["Can it never die?"] = "Có thể nó không bao giờ chết?"
    textfix["Can it play \"O Canada\"?"] = "Nó có thể chơi \"O Canada\" không?"
    textfix["Can it thaw a cold, broken heart?"] = "Liệu nó có thể làm tan chảy một trái tim lạnh giá, tan vỡ?"
    textfix["Can lift it?"] = "Có thể nâng nó lên?"
    textfix["Can little friend get poppy corn?"] = "Người bạn nhỏ có thể lấy được bắp anh túc không?"
    textfix["Can make boat-stopper!"] = "Có thể làm nút chặn thuyền!"
    textfix["Can make more fire later!"] = "Có thể tạo thêm lửa sau này!"
    textfix["Can make own veggies?!"] = "Có thể tự làm rau ?!"
    textfix["Can make the Floaty spin with this"] = "Có thể làm Floaty quay bằng cái này"
    textfix["Can only be crafted at a Combriner."] = "Chỉ có thể được chế tạo tại Combriner."
    textfix["Can only be crafted at a Notional Fabricator."] = "Chỉ có thể được chế tạo tại Máy Chế Tác Hư Ảo."
    textfix["Can only be crafted at a Shadowcraft Plinth."] = "Chỉ có thể chế tạo tại Shadowcraft Plinth."
    textfix["Can only be forged at a Brightsmithy."] = "Chỉ có thể được rèn tại Lò Quang Luyện."
    textfix["Can package up to 4 stacks of items into one item that can be unpacked later."] = "Có thể đóng gói tối đa 4 ngăn của các mặt hàng vào một mặt hàng có thể được giải nén sau đó."
    textfix["Can play dress-up!"] = "Có thể chơi hóa trang!"
    textfix["Can play with fish friends in rain!"] = "Có thể chơi với bạn cá dưới mưa!"
    textfix["Can play with fish friends in snow!"] = "Có thể chơi với bạn bè cá trong tuyết!"
    textfix["Can play with it?"] = "Có thể chơi với nó?"
    textfix["Can poof now!"] = "Có thể gặp sự cố ngay bây giờ!"
    textfix["Can poof to friends now!"] = "Có thể gặp bạn bè ngay bây giờ!"
    textfix["Can receive up to 6 \"wet\" and \"dry\" items. When it has at least 2 items, it begins composting.\n\nThe more items it has the faster it will produce compost.\n\nIt works faster if it has a ballance of \"wet\" and \"dry\" items."] = "Có thể nhận tối đa 6 vật phẩm \"ướt\" và \"khô\". Khi có ít nhất 2 vật phẩm, nó sẽ bắt đầu quá trình ủ phân.\n\nCàng có nhiều vật phẩm thì nó sẽ tạo ra phân trộn càng nhanh.\n\nNó hoạt động nhanh hơn nếu có một khối các vật phẩm \"ướt\" và \"khô\"."
    textfix["Can ride it?... Nope"] = "Có thể cưỡi nó được không?... Không"
    textfix["Can ride now"] = "Có thể đi xe bây giờ"
    textfix["Can science explain why it tastes so good?"] = "Khoa học có thể giải thích tại sao nó có vị ngon như vậy?"
    textfix["Can see cute face in it!"] = "Có thể nhìn thấy khuôn mặt dễ thương trong đó!"
    textfix["Can see everything!"] = "Có thể nhìn thấy mọi thứ!"
